/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A15 checkpoint 1/4: cinematography–civility (20 frozen headwords). */
'use strict';
const D=globalThis.RA.D;
const q=(w,n,s,p,options,answer,explain)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options,answer,explain});
const c=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const put=(w,origin,context,wrong,right,reason,quiz)=>D(w,{etymology:{origin,prefix:null,root:null,suffix:null,source:'Merriam-Webster Dictionary, etymology'},contexts:[context],mistakes:[{errorType:'meaning',wrong,right,reason}],quiz});
put('cinematography','cinematography 由 cinema 与 -graphy（记录、书写的技艺）构成，指电影的摄影和镜头艺术。',c('cinematography.s1','电影制作','The director praised the cinematography because the dawn sequence used natural light and patient, carefully framed shots.','导演称赞了电影摄影，因为黎明场景运用了自然光和耐心构图的镜头。','The director praised the cinematography / because the dawn sequence used natural light and patient, carefully framed shots.','cinematography 是 praised 的宾语；because 从句交代摄影获赞的原因。','自然光、构图和镜头处理属于电影摄影技艺。'),'The cinematography describes only the film’s plot, not how its images were photographed.','The cinematography describes how the film’s images were photographed, not only what its plot is.','cinematography 指影像拍摄的视觉技艺，不等同于剧情。',[q('cinematography',1,1,'What does a cinematographer chiefly shape?',['camera work, lighting, and the visual composition','the legal wording of a film contract','the order of seats in a cinema'],'camera work, lighting, and the visual composition','cinematography.s1 是电影摄影技艺，涵盖镜头、光线与构图。'),q('cinematography',2,1,'A reviewer admires a film’s cinematography. The reviewer most likely praises its?',['visual images and camera work','actors’ private addresses','ticket prices'],'visual images and camera work','称赞 cinematography 是称赞拍摄影像的视觉处理。'),q('cinematography',3,1,'Which choice is an aspect of cinematography?',['framing a moving subject in low light','writing a cinema’s fire-safety rules','selling popcorn before a screening'],'framing a moving subject in low light','取景和光线是电影摄影的组成部分。'),q('cinematography',4,1,'A film can have strong cinematography even if it has?',['a weak plot but strikingly photographed scenes','no photographed or filmed images','only a printed list of movie theaters'],'a weak plot but strikingly photographed scenes','摄影表现和剧情质量是不同方面。')]);
put('cinnamon','cinnamon 经古法语与希腊语进入英语，最终与希伯来语 qinnamon（香料树皮）相关，既指肉桂香料，也指其色泽。',c('cinnamon.s2','服饰色彩','The fox’s cinnamon coat blended with the dry leaves, though its white-tipped tail remained visible against the ground.','狐狸肉桂色的皮毛与枯叶融为一体，不过白色尾尖在地面上仍很显眼。','The fox’s cinnamon coat blended with the dry leaves / though its white-tipped tail remained visible against the ground.','cinnamon 作形容词修饰 coat；though 从句形成颜色上的对照。','形容皮毛为肉桂色，体现 cinnamon.s2 的浅赤褐色义。'),'She added cinnamon to the recipe for its bright blue colour and salty flavour.','She added cinnamon to the recipe for its warm aroma and sweet, spicy flavour.','肉桂是芳香甜辛的香料，不是蓝色咸味调料。',[q('cinnamon',1,1,'What is cinnamon commonly used for?',['flavouring food with an aromatic spice','making a dish taste strongly of salt','turning a sauce naturally bright blue'],'flavouring food with an aromatic spice','cinnamon.s1 是肉桂香料，常用于调味。'),q('cinnamon',2,2,'A cinnamon-brown scarf is closest to which colour?',['light reddish brown','bright turquoise','pure white'],'light reddish brown','肉桂色是浅赤褐色。'),q('cinnamon',3,1,'Which ingredient could be ground cinnamon?',['powdered aromatic bark used in baking','dried fish skin used as a garnish','crushed ice from a drink'],'powdered aromatic bark used in baking','肉桂粉由香料树皮制成，可用于烘焙。'),q('cinnamon',4,2,'A cinnamon-coloured horse would have a coat that is?',['warm reddish brown','dark green with blue stripes','transparent'],'warm reddish brown','此处 cinnamon 作颜色形容词。')]);
put('circadian','circadian 由拉丁语 circa diem（大约一天）构成，用来形容约每二十四小时重复的生物节律。',c('circadian.s1','睡眠科学','Night-shift workers often keep a dark bedroom for daytime sleep because bright morning light can reset their circadian clock.','夜班工人常把卧室保持昏暗以便白天睡觉，因为清晨强光会重设他们的昼夜生物钟。','Night-shift workers often keep a dark bedroom for daytime sleep / because bright morning light can reset their circadian clock.','circadian 修饰 clock；because 从句说明光线与生物节律的关系。','生物钟约按一天为周期运行，符合 circadian.s1。'),'A circadian rhythm repeats every few minutes and has no relation to a roughly daily cycle.','A circadian rhythm repeats on a roughly daily cycle.','circadian 描述约二十四小时的周期，而非数分钟的重复。',[q('circadian',1,1,'A circadian rhythm has a period of roughly?',['one day','one minute','one century'],'one day','circadian.s1 指大约一天的生物周期。'),q('circadian',2,1,'Which process is commonly regulated by a circadian clock?',['the sleep–wake cycle','the number of bones in a hand','the annual migration of continents'],'the sleep–wake cycle','睡眠—觉醒节律是常见的昼夜节律。'),q('circadian',3,1,'A flight across time zones may disrupt a traveler’s?',['circadian rhythm','shoe size','blood type'],'circadian rhythm','时差会扰乱大约按一天循环的生物节律。'),q('circadian',4,1,'Which statement fits a circadian pattern?',['a hormone level that normally rises and falls over each day','a one-off event that never repeats','a sound wave that repeats thousands of times each second'],'a hormone level that normally rises and falls over each day','按日重复的激素变化符合 circadian 的定义。')]);
put('circuitous','circuitous 源于拉丁语 circuitus（绕行、环绕），由 circuit 加形容词后缀 -ous 构成，表示路线或表达迂回。',c('circuitous.s1','城市交通','Because the riverside bridge was closed, the bus followed a circuitous route through three neighbouring districts before reaching the station.','由于河边大桥关闭，公交车绕行三个相邻城区后才到达车站。','Because the riverside bridge was closed / the bus followed a circuitous route through three neighbouring districts / before reaching the station.','circuitous 修饰 route；because 和 before 分别交代原因与终点。','路线为避开封桥绕行多个城区，体现迂回义。'),'We took a circuitous route that went straight to the station by the shortest road.','We took a direct route that went straight to the station by the shortest road.','最短直达路线不迂回；direct 是合适修正。',[q('circuitous',1,1,'A circuitous route is?',['long and indirect','the shortest possible route','a route with no turns or distance'],'long and indirect','circuitous.s1 指不直接、绕远的路线。'),q('circuitous',2,1,'A circuitous explanation would probably?',['reach its point by taking unnecessary detours','state its point immediately and briefly','contain no words at all'],'reach its point by taking unnecessary detours','此词也可形容表达冗长绕弯。'),q('circuitous',3,1,'Why might a driver choose a circuitous road?',['a direct road is blocked, so the driver must go around','the driver wants the shortest straight path','the destination is inside the car'],'a direct road is blocked, so the driver must go around','因道路受阻而绕行，形成迂回路线。'),q('circuitous',4,1,'Which route is most circuitous?',['a three-district detour around a closed bridge','a clear road straight to the destination','a short path across an open bridge'],'a three-district detour around a closed bridge','绕过封桥并经过多个城区的路线最迂回。')]);
put('circulatory','circulatory 由 circulate 加形容词后缀 -ory 构成，指血液或其他物质在系统内循环流动的。',c('circulatory.s1','健康教育','A brisk walk raises the heart rate and encourages blood to move efficiently through the circulatory system.','快步走会提高心率，并促进血液在循环系统中有效流动。','A brisk walk raises the heart rate / and encourages blood to move efficiently through the circulatory system.','circulatory 修饰 system；through 短语说明血液流经系统。','血液在体内流动是 circulatory.s1 的核心。'),'The circulatory system carries blood only outside the body and has no connection to blood flow.','The circulatory system carries blood through the body and is essential to blood flow.','循环系统负责体内血液循环，并非体外运输。',[q('circulatory',1,1,'The circulatory system is chiefly concerned with?',['movement of blood through the body','the digestion of food in the stomach','the formation of spoken sentences'],'movement of blood through the body','circulatory.s1 与血液在体内的循环有关。'),q('circulatory',2,1,'A circulatory problem might involve?',['blood flow through vessels','the colour of a person’s handwriting','the orbit of a planet'],'blood flow through vessels','血管内血流属于循环系统功能。'),q('circulatory',3,1,'Which organ works as a pump in the circulatory system?',['the heart','the kneecap','the outer ear'],'the heart','心脏推动血液在循环系统内流动。'),q('circulatory',4,1,'A doctor studying circulatory health would examine?',['how blood moves around the body','how clouds form over a sea','how a musical instrument is tuned'],'how blood moves around the body','这直接对应 circulatory 的血液循环义。')]);
put('circumcision','circumcision 由拉丁语 circumcidere（从周围切除）经法语进入英语，指切除包皮的手术或仪式。',c('circumcision.s1','医学史','The medical record stated that circumcision had been performed in infancy and that the patient had recovered without complications.','病历记载患者婴儿期接受过包皮环切术，且恢复时没有并发症。','The medical record stated that circumcision had been performed in infancy / and that the patient had recovered without complications.','circumcision 是 stated 的宾语从句主语；过去完成被动交代此前实施的手术。','病历中的手术明指包皮环切，符合该义项。'),'The procedure called circumcision removes a fingernail while leaving the foreskin untouched.','The procedure called circumcision removes the foreskin while leaving the fingernails untouched.','circumcision 是切除包皮的手术，不是修剪指甲。',[q('circumcision',1,1,'Circumcision is a procedure involving the removal of the?',['foreskin','appendix','tonsils'],'foreskin','circumcision.s1 指切除阴茎包皮的手术。'),q('circumcision',2,1,'Which setting may include circumcision?',['a medical or religious context','a routine eye test','a music lesson'],'a medical or religious context','该手术可出于医疗、文化或宗教原因。'),q('circumcision',3,1,'A hospital note saying circumcision was performed records?',['a surgical procedure','a blood-type measurement','a dental filling'],'a surgical procedure','circumcision 是手术，也可能是仪式。'),q('circumcision',4,1,'Which description is accurate?',['an operation that removes the foreskin','an operation that removes a fingernail','a procedure that measures body temperature'],'an operation that removes the foreskin','这准确说明 circumcision 的医学义。')]);
put('circumference','circumference 经古法语来自拉丁语 circumferentia（环绕、周边），由 circum（周围）与 ferre（带、承载）构成，指围绕物体的长度。',c('circumference.s2','服装测量','The tailor measured the circumference of the customer’s waist twice, then checked the number against the pattern before cutting the cloth.','裁缝量了顾客腰围两次，随后在裁剪布料前对照纸样核对尺寸。','The tailor measured the circumference of the customer’s waist twice / then checked the number against the pattern / before cutting the cloth.','circumference 是 measured 的宾语，of 短语指出测量部位。','腰部周围的尺寸是 circumference.s2。'),'The waist circumference is the distance from the shoulder to the ankle, not around the waist.','The waist circumference is the distance around the waist, not from the shoulder to the ankle.','circumference 是绕某处一周的尺寸，不是纵向长度。',[q('circumference',1,1,'The circumference of a circle is the distance?',['around its boundary','from its centre to its edge','across its widest part through the centre'],'around its boundary','circumference.s1 是圆周一圈的长度。'),q('circumference',2,2,'A tailor measuring waist circumference measures?',['the distance around the waist','the person’s height','the width of one shoulder'],'the distance around the waist','人体部位的 circumference 指围度。'),q('circumference',3,1,'A flexible tape is useful for finding a tree trunk’s?',['circumference','temperature','age in years without other evidence'],'circumference','将软尺绕树干一周可量其周长。'),q('circumference',4,2,'If a waist’s circumference increases, the measurement around it has?',['become larger','become the person’s height','turned into a radius'],'become larger','围度增加就是环绕腰部的尺寸增大。')]);
put('circumjacent','circumjacent 由拉丁语 circum（周围）与 iacere（躺、位于）构成，形容环绕或四面毗连的事物。',c('circumjacent.s1','地理描述','The village’s circumjacent hills shelter its orchards from cold winds, while a narrow pass opens toward the northern plain.','村庄周边的山丘为果园挡住寒风，而一条狭窄山口通向北部平原。','The village’s circumjacent hills shelter its orchards from cold winds / while a narrow pass opens toward the northern plain.','circumjacent 作定语修饰 hills；while 对照山丘与山口的作用。','山丘环绕村庄，符合 circumjacent.s1。'),'The circumjacent hills stood hundreds of miles away and did not lie around the village.','The distant hills stood hundreds of miles away and did not lie around the village.','circumjacent 意为位于四周，远在数百英里外便不能这样描述。',[q('circumjacent',1,1,'Circumjacent buildings are buildings that?',['lie around or border the place in question','stand far away with no spatial relation','have been built beneath the sea'],'lie around or border the place in question','circumjacent.s1 表示环绕或四周毗连。'),q('circumjacent',2,1,'A circumjacent wall would most likely?',['surround the garden','hang inside a person’s pocket','run only through the centre of a lake'],'surround the garden','墙围在花园四周，体现“环绕”。'),q('circumjacent',3,1,'Which is a circumjacent feature of a valley?',['the hills bordering it on every side','a ship crossing an unrelated ocean','a cloud far above another country'],'the hills bordering it on every side','四面毗连山谷的山丘是周边地物。'),q('circumjacent',4,1,'The meaning of circumjacent is closest to?',['surrounding','unrelated','underground'],'surrounding','circumjacent 与 surrounding 意义相近。')]);
put('circumscribe','circumscribe 由拉丁语 circum（周围）与 scribere（写、画）构成，原指画线围住，后引申为限制范围。',c('circumscribe.s2','几何课堂','To circumscribe the triangle, the students drew a circle that passed through all three vertices.','为了外接于三角形，学生们画了一个经过三个顶点的圆。','To circumscribe the triangle / the students drew a circle that passed through all three vertices.','circumscribe 是不定式目的动词；that 从句限定所画圆。','圆包围三角形并经过其顶点，体现 circumscribe.s2 的几何义。'),'The circle circumscribed the triangle by cutting through its centre and leaving every vertex outside.','The circle circumscribed the triangle by passing through its vertices and enclosing it.','几何上的 circumscribe 是外接包围，不是把顶点留在圆外。',[q('circumscribe',1,1,'A law that circumscribes a power?',['limits the power’s range','increases it without limit','describes its colour'],'limits the power’s range','circumscribe.s1 表示限制范围或自由。'),q('circumscribe',2,2,'In geometry, to circumscribe a triangle with a circle is to?',['draw a circle around it through its vertices','draw a line through only its centre','erase all three vertices'],'draw a circle around it through its vertices','circumscribe.s2 指画线包围图形，外接圆经过顶点。'),q('circumscribe',3,1,'A circumscribed budget would be?',['restricted by a limit','free of every restriction','a geometric angle'],'restricted by a limit','比喻义是给范围设限。'),q('circumscribe',4,2,'Which drawing shows a circle circumscribing a triangle?',['a circle passes through all three corners','a circle sits far away from the triangle','a line divides the triangle into two pieces'],'a circle passes through all three corners','圆经过三角形各顶点并包围它。')]);
put('circumspect','circumspect 由拉丁语 circumspicere（环顾四周、谨慎观察）构成，形容行事谨慎或全面考虑各种可能。',c('circumspect.s2','谈判策略','Before discussing the disputed boundary, both delegations were circumspect about wording and reviewed each possible interpretation.','在讨论有争议的边界之前，双方代表团对措辞都很审慎，并逐一检查各种可能的解释。','Before discussing the disputed boundary / both delegations were circumspect about wording / and reviewed each possible interpretation.','circumspect 作表语；about 指谨慎之处，and 连接审查行动。','谨慎措辞并考虑多种解释，体现 circumspect.s2。'),'The negotiator was circumspect and signed the first proposal without reading any of its terms.','The negotiator was incautious and signed the first proposal without reading any of its terms.','不看条款便贸然签署表现鲁莽，而非 circumspect。',[q('circumspect',1,1,'A circumspect decision-maker is?',['careful about risks before acting','eager to ignore every possible danger','unable to understand written language'],'careful about risks before acting','circumspect.s1 指谨慎、不冒险。'),q('circumspect',2,2,'Someone circumspect about several outcomes?',['thinks carefully about those possibilities','refuses to consider any of them','chooses randomly before learning them'],'thinks carefully about those possibilities','circumspect.s2 强调全面考虑各种可能。'),q('circumspect',3,1,'Which action is most circumspect?',['checking the contract’s consequences before signing','signing an unread contract immediately','discarding every warning without review'],'checking the contract’s consequences before signing','先审查后签署是谨慎周全的做法。'),q('circumspect',4,2,'Why might a witness give a circumspect answer?',['to avoid claiming more than the evidence supports','to make a careless guess sound certain','to change the subject to the weather'],'to avoid claiming more than the evidence supports','谨慎回答会考虑证据及可能后果。')]);
put('circumstantially','circumstantially 由 circumstance 加副词后缀 -ally 构成，可指依据具体情形，或依据间接情况证据。',c('circumstantially.s2','法庭证据','No camera recorded the break-in, but the suspect was linked to it circumstantially by fingerprints and a matching vehicle track.','没有摄像机拍下闯入过程，但指纹和吻合的车辙构成间接证据，将嫌疑人与事件联系起来。','No camera recorded the break-in / but the suspect was linked to it circumstantially / by fingerprints and a matching vehicle track.','circumstantially 修饰 was linked；by 短语说明旁证内容。','指纹和车辙支持推断但非直接目击，符合 s2。'),'The jury proved the suspect circumstantially with a clear recording that directly showed the act.','The jury proved the suspect directly with a clear recording that showed the act.','直接录像是直接证据，不能称为依据间接情况证据。',[q('circumstantially',1,1,'If a case is proved circumstantially, the conclusion relies on?',['indirect facts that support an inference','a witness who directly saw every act','no evidence of any kind'],'indirect facts that support an inference','circumstantially.s2 指依据间接旁证推断。'),q('circumstantially',2,2,'Which item is circumstantial evidence of a break-in?',['a fingerprint found at the scene','a video showing the suspect enter','a signed confession describing the entry'],'a fingerprint found at the scene','现场指纹提供关联线索，但不直接显示行为过程。'),q('circumstantially',3,1,'A circumstantial argument reaches a conclusion?',['from surrounding facts rather than direct proof','without any supporting facts','by measuring a circle’s perimeter'],'from surrounding facts rather than direct proof','旁证是由相关情况推断结论。'),q('circumstantially',4,2,'The opposite of proving something circumstantially is proving it?',['directly with direct evidence','only by guessing','through unrelated circumstances'],'directly with direct evidence','直接证据与间接情形证据形成对照。')]);
put('circumvent','circumvent 经古法语与拉丁语 circumvenire（绕行、欺骗）进入英语，由 circum（周围）与 venire（来）构成，现代常指巧妙避开规则或障碍。',c('circumvent.s1','法规合规','The importer could not circumvent the safety inspection by relabelling the crates, because customs checked the serial numbers as well.','进口商无法靠重新贴标签规避安全检查，因为海关也核对了序列号。','The importer could not circumvent the safety inspection by relabelling the crates / because customs checked the serial numbers as well.','circumvent 是情态动词 could not 后的原形；by 说明尝试的规避方式。','设法绕过检查规则正是 circumvent.s1。'),'The importer circumvented the inspection by following every required step and presenting all documents openly.','The importer complied with the inspection by following every required step and presenting all documents openly.','遵守规定并不等于规避；complied 是贴切的替换。',[q('circumvent',1,1,'To circumvent a regulation is to?',['find a way around it','write it down exactly','make it stricter for everyone'],'find a way around it','circumvent.s1 表示巧妙绕过规则或障碍。'),q('circumvent',2,1,'A hacker tries to circumvent a password check by?',['bypassing the security step','asking an administrator to reset it properly','entering the correct password'],'bypassing the security step','绕过验证步骤就是试图 circumvent。'),q('circumvent',3,1,'Which action would circumvent a ban?',['using a hidden route to continue the prohibited sale','stopping the sale as the ban requires','asking lawmakers to repeal the ban publicly'],'using a hidden route to continue the prohibited sale','暗中避开禁令继续销售，符合规避义。'),q('circumvent',4,1,'A detour that avoids a blocked road circumvents?',['the obstacle','the destination itself','the vehicle’s colour'],'the obstacle','circumvent 可指绕过困难或阻挡。')]);
put('citadel','citadel 经意大利语 cittadella（小城、要塞）进入英语，最终来自拉丁语 civitas（城市），指保护城市的坚固堡垒。',c('citadel.s1','历史遗址','From the citadel above the harbour, guards could watch the main road and signal when ships approached the fortified town.','从港口上方的城堡，守卫可以监视主路，并在船只接近设防城镇时发出信号。','From the citadel above the harbour / guards could watch the main road / and signal when ships approached the fortified town.','citadel 作 from 的宾语；above 指其居高临下的位置。','守望港口、保卫城市的高处要塞符合 citadel.s1。'),'The town’s citadel was an unfortified picnic tent with no defensive purpose.','The town’s pavilion was an unfortified picnic tent with no defensive purpose.','citadel 是防御堡垒，野餐帐篷不是要塞。',[q('citadel',1,1,'A citadel is best described as?',['a strong fort defending or overlooking a city','a temporary market stall','a shallow pond in a garden'],'a strong fort defending or overlooking a city','citadel.s1 指防御城市的坚固堡垒。'),q('citadel',2,1,'Why was a citadel often built on high ground?',['to observe and defend the city','to hide from every resident','to grow crops below the soil'],'to observe and defend the city','高处要塞便于观察并守卫城市。'),q('citadel',3,1,'Which building could serve as a citadel?',['a fortified stronghold above an old harbour','an open-air café with no walls','a wooden footbridge over a stream'],'a fortified stronghold above an old harbour','设防并俯瞰港口的堡垒符合 citadel。'),q('citadel',4,1,'In “a citadel of independent thought,” citadel is used?',['figuratively for a stronghold','as a kind of spice','as a unit of distance'],'figuratively for a stronghold','citadel 还可比喻坚强据点。')]);
put('citation','citation 经法语来自拉丁语 citare（传唤、引用），指引用的文字或来源、引用行为，也可指正式表彰。',c('citation.s3','公共荣誉','The firefighter received a citation for bravery after leading two residents out of the smoke-filled apartment building.','这名消防员因勇敢救出两位居民而获得嘉奖。','The firefighter received a citation for bravery / after leading two residents out of the smoke-filled apartment building.','citation 是 received 的宾语；for 短语说明表彰原因。','因英勇行为颁发的正式嘉奖属于 citation.s3。'),'The officer issued a citation for bravery to punish the firefighter for saving two residents.','The officer issued a citation for bravery to honour the firefighter for saving two residents.','for bravery 表明是表彰行为，不是处罚救人。',[q('citation',1,1,'A citation in an essay usually identifies?',['a quoted source or passage','the author’s shoe size','the paper’s printing cost'],'a quoted source or passage','citation.s1 是引用的文字或出处。'),q('citation',2,2,'Citation of a source is the act of?',['mentioning or quoting that source','hiding it from the reader','changing its publication date'],'mentioning or quoting that source','citation.s2 指引用来源这一行为。'),q('citation',3,3,'A citation for bravery is most likely?',['an official commendation','a fine for speeding','a map of a city wall'],'an official commendation','citation.s3 可指正式表彰或嘉奖令。'),q('citation',4,1,'Why add a citation after a quotation?',['to show where the quoted words came from','to make the quotation anonymous','to claim the quote has no author'],'to show where the quoted words came from','引文 citation 标明文字来源。')]);
put('cither','cither 是历史乐器名称，经中古英语承袭于古法语 citole，并与拉丁语 cithara（齐特拉琴）同源，指拨弦乐器。',c('cither.s1','音乐史','A conservator tuned the museum’s cither gently, plucking each string while comparing its resonance with an archival recording.','修复师轻轻调试博物馆里的齐特琴，一边拨动琴弦，一边将共鸣与档案录音对照。','A conservator tuned the museum’s cither gently / plucking each string / while comparing its resonance with an archival recording.','cither 是 tuned 的宾语；分词短语说明调音动作。','拨弦并有多根琴弦的历史乐器符合 cither.s1。'),'The cither is a brass wind instrument played by blowing air through a mouthpiece.','The cither is a plucked string instrument played by setting its strings vibrating.','cither 是拨弦乐器，不是吹奏的铜管乐器。',[q('cither',1,1,'A cither belongs to which instrument family?',['plucked string instruments','brass wind instruments','percussion drums only'],'plucked string instruments','cither.s1 是齐特琴类的拨弦乐器。'),q('cither',2,1,'How would a musician normally produce sound on a cither?',['by plucking its strings','by blowing through a reed','by striking a large gong'],'by plucking its strings','cither 通过拨动琴弦发声。'),q('cither',3,1,'A museum label calls an object a cither. One should expect?',['an old stringed instrument related to the zither','a modern electric keyboard','a type of drumstick'],'an old stringed instrument related to the zither','它是与 cittern 或 zither 相近的历史弦乐器。'),q('cither',4,1,'Which action best fits playing a cither?',['plucking a course of strings','blowing into a brass tube','bowing a violin string with a bow'],'plucking a course of strings','拨弦是演奏此类乐器的方式。')]);
put('citizenry','citizenry 由 citizen 与集合名词后缀 -ry 构成，指某地公民作为整体的群体。',c('citizenry.s1','地方治理','The citizenry packed the town hall to question the council about water restrictions and the cost of repairing the old pipes.','全体市民挤满了市政厅，质询委员会关于限水和维修旧水管费用的问题。','The citizenry packed the town hall / to question the council / about water restrictions and the cost of repairing the old pipes.','集合名词 citizenry 作 packed 的主语；to 不定式说明到场目的。','作为整体参与公共事务的是 citizenry.s1。'),'The citizenry means one visiting tourist who holds no citizenship in the town.','The citizenry means the town’s citizens considered together, not one visiting tourist.','citizenry 是公民群体，不是单个游客。',[q('citizenry',1,1,'A city’s citizenry is?',['its citizens considered as a group','one elected official alone','all visitors from other countries only'],'its citizens considered as a group','citizenry.s1 指全体公民。'),q('citizenry',2,1,'A report says the citizenry demanded clean water. Who made the demand?',['the people who are citizens there, collectively','a single visiting scientist only','the pipes themselves'],'the people who are citizens there, collectively','citizenry 作集合名词，指公民整体。'),q('citizenry',3,1,'Which phrase is closest in meaning to citizenry?',['the body of a country’s citizens','the country’s mineral resources','a list of foreign tourists'],'the body of a country’s citizens','citizenry 即某地全体公民。'),q('citizenry',4,1,'The word citizenry emphasizes?',['a collective body of citizens','a single person’s passport photograph','a city’s buildings'],'a collective body of citizens','后缀 -ry 在此形成群体总称。')]);
put('citizenship','citizenship 由 citizen 加抽象名词后缀 -ship 构成，表示公民在国家中的法律身份及相应权利义务。',c('citizenship.s1','公民身份','After living in the country for several years, Amira applied for citizenship and studied the rights and duties listed in the official guide.','在这个国家生活数年后，阿米拉申请了公民身份，并学习官方指南列出的权利和义务。','After living in the country for several years / Amira applied for citizenship / and studied the rights and duties listed in the official guide.','citizenship 是 applied for 的宾语；and 连接申请与了解权责。','申请法律上的公民身份并了解权利义务，对应 citizenship.s1。'),'Citizenship is a tourist’s hotel reservation and carries no legal relation to a state.','Citizenship is a person’s legal relation to a state, with associated rights and duties.','citizenship 是与国家的法律身份关系，不是酒店预订。',[q('citizenship',1,1,'Citizenship primarily refers to?',['a person’s legal status as a member of a state','a temporary hotel booking','the language spoken at home only'],'a person’s legal status as a member of a state','citizenship.s1 指公民身份及其法律关系。'),q('citizenship',2,1,'Someone applying for citizenship is seeking?',['legal membership and its rights and duties','a short-term visitor’s parking permit','a new profession in the military'],'legal membership and its rights and duties','申请 citizenship 是申请成为该国公民。'),q('citizenship',3,1,'Dual citizenship means a person has?',['citizenship in two countries','two homes in one city','two names but no nationality'],'citizenship in two countries','dual citizenship 指具有两个国家的公民身份。'),q('citizenship',4,1,'Which issue belongs to citizenship?',['the legal duties owed by citizens','the flavour of a spice','the length around a circle'],'the legal duties owed by citizens','公民义务属于 citizenship 的法律内涵。')]);
put('citric','citric 经法语 citrique 来自拉丁语 citrus，指柑橘类或从这类果实得到的酸。',c('citric.s1','食品化学','The label lists citric acid as an ingredient; it gives the fruit drink a tart taste and also helps regulate its acidity.','标签把柠檬酸列为成分；它使果饮带有酸味，也有助于调节酸度。','The label lists citric acid as an ingredient / it gives the fruit drink a tart taste / and also helps regulate its acidity.','citric 修饰 acid；分号连接成分及其作用。','柠檬酸来源于柑橘类果实，属于 citric.s1。'),'Citric acid is a sweet protein found only in animal muscle and unrelated to fruit.','Citric acid is an organic acid found naturally in citrus fruits and used to give foods a tart taste.','citric 指柑橘或柠檬酸相关，原句的动物蛋白说法不符。',[q('citric',1,1,'Citric acid is closely associated with?',['citrus fruit','iron tools','woven fabric'],'citrus fruit','citric.s1 指柑橘类或由其获得的酸。'),q('citric',2,1,'A citric-acid cycle is a term used in?',['biochemistry','shipbuilding','musical notation'],'biochemistry','citric acid cycle 是生物化学中的术语。'),q('citric',3,1,'Which product might contain citric acid?',['a tart lemon-flavoured drink','a dry wooden ruler','a wool blanket with no additives'],'a tart lemon-flavoured drink','柠檬酸常见于饮料，可提供酸味并调酸。'),q('citric',4,1,'The adjective citric most directly means?',['relating to citrus fruit or its acid','made of copper','related to the citizenry'],'relating to citrus fruit or its acid','citric 来源于 citrus，表示柑橘相关。')]);
put('civet','civet 的词源经法语 civette 可追溯至阿拉伯语 zabād，原指灵猫分泌的强烈麝香物，词也指这种夜行哺乳动物。',c('civet.s2','香料史','Before synthetic substitutes became common, some perfume makers used civet sparingly because its animal musk had a powerful, persistent scent.','在合成替代品普及前，一些香水制造者会少量使用灵猫香，因为这种动物麝香气味浓烈而持久。','Before synthetic substitutes became common / some perfume makers used civet sparingly / because its animal musk had a powerful, persistent scent.','civet 是 used 的宾语；because 从句说明使用量少的原因。','香水中的动物麝香体现 civet.s2。'),'The perfume contained civet, a scentless mineral powder mined from a salt cave.','The perfume contained civet, a strong-smelling musk once obtained from the animal.','civet 的此义是动物分泌的麝香物，并非矿物粉末。',[q('civet',1,1,'A civet is an animal best described as?',['a slender, often nocturnal mammal','a large flightless bird','a freshwater fish'],'a slender, often nocturnal mammal','civet.s1 指非洲或亚洲的灵猫类哺乳动物。'),q('civet',2,2,'In perfumery, civet can refer to?',['the animal’s musky secretion','a citrus peel used as a plate','a colourless cooking oil'],'the animal’s musky secretion','civet.s2 指灵猫产生的麝香物。'),q('civet',3,1,'Which habitat clue fits a civet?',['a forest at night in parts of Africa or Asia','an icy ocean under polar ice','a treeless desert at noon only'],'a forest at night in parts of Africa or Asia','灵猫常为非洲或亚洲的夜行兽。'),q('civet',4,2,'Why was civet historically used in some perfumes?',['its strong musky scent','its ability to bleach fabric white','its sweet taste in baked bread'],'its strong musky scent','动物麝香的气味使其曾用于香水。')]);
put('civilise','civilise 是英式拼写，由 civil 加动词后缀 -ise 构成，原与拉丁语 civilis（公民的、公共生活的）相关，可指改善社会制度或举止。',c('civilise.s1','社会史','The reformers argued that public schools could civilise society by teaching literacy, civic duties, and peaceful ways to resolve disputes.','改革者认为公立学校可以通过教授读写、公民责任和和平解决争端的方式，使社会更加文明。','The reformers argued that public schools could civilise society / by teaching literacy, civic duties, and peaceful ways to resolve disputes.','civilise 是情态动词 could 后的原形；by 短语说明手段。','改善社会制度与公共行为，体现 civilise.s1。'),'The policy would civilise the town by abolishing schools and replacing its laws with arbitrary violence.','The policy would civilise the town by expanding education and strengthening fair public institutions.','教育与公平制度可被描述为改善公共生活；任意暴力与此相反。',[q('civilise',1,1,'To civilise a society is to?',['develop its institutions and social practices','make its people less educated','remove every public rule'],'develop its institutions and social practices','civilise.s1 指使社会形成被视为较完善的制度与习惯。'),q('civilise',2,1,'A school might be said to civilise pupils by teaching?',['literacy and respectful public conduct','how to avoid all learning','how to damage shared facilities'],'literacy and respectful public conduct','教育读写和公共礼仪属于改善行为的例子。'),q('civilise',3,1,'Civilise is the spelling commonly used in?',['British English','the Greek alphabet','mathematical notation'],'British English','-ise 是常见英式拼写；美式多写 civilize。'),q('civilise',4,1,'Which reform could plausibly be described as civilising?',['establishing fair courts and accessible schools','closing courts and banning education','encouraging disputes to be settled by violence'],'establishing fair courts and accessible schools','完善司法与教育制度可改善社会生活。')]);
put('civility','civility 经古法语 civilité 来自拉丁语 civilitas（公民生活、礼貌），指礼貌行为，也可指客套举止或言辞。',c('civility.s2','社交礼节','Although the neighbours disagreed about the fence, they exchanged a few civilities before calmly discussing where the boundary lay.','尽管邻居们对围栏意见不一，他们仍互致了几句客套，然后平静地讨论界线的位置。','Although the neighbours disagreed about the fence / they exchanged a few civilities / before calmly discussing where the boundary lay.','civilities 是 exchanged 的宾语，复数表示具体客套话或礼节。','互致的几句寒暄是 civility.s2 的可数用法。'),'The neighbours exchanged civilities by insulting one another and refusing to say hello.','The neighbours exchanged civilities by greeting one another politely before discussing the dispute.','civility 指礼貌客套，辱骂与拒绝问候不符合其义。',[q('civility',1,1,'Civility in public conversation means?',['polite and courteous behaviour','a loud demand for a prize','a legal status in another country'],'polite and courteous behaviour','civility.s1 指礼貌、客气的行为。'),q('civility',2,2,'They exchanged civilities before the meeting. They exchanged?',['polite greetings or remarks','official fines','secret legal documents'],'polite greetings or remarks','复数 civilities 可指客套话或礼节。'),q('civility',3,1,'Which response shows civility during a disagreement?',['“I see your point; may I explain my concern?”','“You are stupid; I will not listen.”','silently tearing up the other person’s notes'],'“I see your point; may I explain my concern?”','礼貌表达异议体现 civility。'),q('civility',4,2,'In “They exchanged civilities and left,” civilities are?',['brief polite social remarks','a formal change of nationality','a set of mathematical ratios'],'brief polite social remarks','此处复数指互相说的礼貌客套话。')]);
put('civilization','civilization 经法语来自拉丁语 civilis（公民的），由 civilize 加 -ation 构成，可指文明社会、发展程度或特定历史文明。',c('civilization.s3','古代史','The Indus Valley civilization built planned cities with drainage systems, standardized bricks, and networks for trade.','印度河流域文明建造了规划有序的城市，设有排水系统、规格统一的砖块和贸易网络。','The Indus Valley civilization built planned cities / with drainage systems, standardized bricks, and networks for trade.','civilization 作 built 的主语中心；专名限定具体历史文明。','特定时空中的社会形态对应 civilization.s3。'),'The Indus Valley civilization refers to one modern household and its private dinner routine.','The Indus Valley civilization refers to an ancient society and its organized culture.','专名 civilization 指一段时期的群体社会文化，不是单个家庭。',[q('civilization',1,1,'A civilization in the broad sense is?',['a highly organized human society and culture','a single person’s daily meal','a method for measuring rainfall'],'a highly organized human society and culture','civilization.s1 指发展成熟的人类社会及其文化。'),q('civilization',2,2,'In “the civilization of the region advanced,” civilization emphasizes?',['the state of social and cultural development','one quotation in a paper','a person’s legal passport status'],'the state of social and cultural development','civilization.s2 表示社会文化的开化程度。'),q('civilization',3,3,'“Maya civilization” names?',['a particular society in a specific historical setting','every human society as one undifferentiated whole','a single architectural measurement'],'a particular society in a specific historical setting','专有的历史社会形态属于 civilization.s3。'),q('civilization',4,1,'Which is evidence of a developed civilization?',['planned settlements, shared institutions, and skilled crafts','one isolated footprint with no cultural context','a cloudburst over an empty field'],'planned settlements, shared institutions, and skilled crafts','有组织的社会生活与文化技艺体现文明。')]);
put('civilize','civilize 由 civil 加动词后缀 -ize 构成，词源关联拉丁语 civilis（公民的），指改善个人举止或社会制度。',c('civilize.s1','行为养成','Years of travel did not civilize his table manners; he still spoke with his mouth full and ignored the shared dishes.','多年的旅行并没有使他的餐桌礼仪变得文雅；他仍然嘴里含着食物说话，也不顾公用菜肴。','Years of travel did not civilize his table manners / he still spoke with his mouth full / and ignored the shared dishes.','civilize 是 did not 后的动词原形，宾语为 table manners。','改善举止礼仪是 civilize.s1 的含义。'),'The school hoped to civilize its halls by encouraging vandalism and discouraging respectful conduct.','The school hoped to civilize its halls by discouraging vandalism and encouraging respectful conduct.','文明化举止与鼓励破坏、拒绝尊重行为相矛盾。',[q('civilize',1,1,'To civilize a person’s manners is to?',['make the behaviour more refined and considerate','teach the person to ignore every social rule','remove the person’s legal citizenship'],'make the behaviour more refined and considerate','civilize.s1 指改善个人礼仪或行为。'),q('civilize',2,1,'Which change could civilize a public institution?',['adopting fair procedures and accessible education','replacing rules with arbitrary violence','closing every school and library'],'adopting fair procedures and accessible education','完善制度及教育可改善社会生活。'),q('civilize',3,1,'Civilize is most naturally used with which object?',['table manners','the circumference of a circle','a shipment’s serial number'],'table manners','manners 是可被改善的行为方式。'),q('civilize',4,1,'Which statement best illustrates civilize?',['The program taught children to resolve disputes without violence.','The program taught children to destroy their neighbours’ property.','The program measured the children’s height.'],'The program taught children to resolve disputes without violence.','学习和平解决争端可改善公共行为。')]);
put('civilized','civilized 是 civilize 的过去分词形容词，可描述制度成熟的社会，也可指有礼貌、讲道理的行为。',c('civilized.s2','日常交往','After the heated vote, the committee held a civilized discussion in which each member waited for others to finish speaking.','激烈表决后，委员会进行了文明而理性的讨论，每位成员都等别人说完再发言。','After the heated vote / the committee held a civilized discussion / in which each member waited for others to finish speaking.','civilized 作定语修饰 discussion；in which 从句说明讨论方式。','轮流发言、理性讨论体现 civilized.s2。'),'The guests had a civilized conversation by shouting over one another and throwing plates.','The guests had a civilized conversation by taking turns and speaking respectfully.','文明交谈应有礼貌与克制，不包括互相喊叫、摔盘子。',[q('civilized',1,1,'A civilized society is one with?',['developed institutions and social organization','no shared culture or public rules','only a large population'],'developed institutions and social organization','civilized.s1 描述社会制度和文化发展程度。'),q('civilized',2,2,'A civilized reply is likely to be?',['polite and reasonable','insulting and threatening','unrelated to the question'],'polite and reasonable','civilized.s2 描述礼貌、讲理的行为。'),q('civilized',3,2,'Which meeting remained civilized despite disagreement?',['participants listened and answered without insults','participants shouted down every speaker','participants overturned the table'],'participants listened and answered without insults','理性倾听和回应符合 civilized 的行为义。'),q('civilized',4,1,'In “a civilized city with reliable courts,” civilized refers chiefly to?',['social development and organized institutions','the city’s cinnamon-coloured roofs','a single resident’s handwriting'],'social development and organized institutions','法院等制度体现社会组织与发展。')]);
put('clam','clam 的词源不确定，英语早期记录已指双壳贝类；作动词时可指挖蛤蜊，短语 clam up 则表示突然沉默。',c('clam.s3','海岸采集','At low tide the children clam for an hour, checking each shallow hole and returning undersized shellfish to the mud.','退潮时孩子们挖了一个小时蛤蜊，逐个检查浅洞，并把未长成的贝类放回泥中。','At low tide / the children clam for an hour / checking each shallow hole / and returning undersized shellfish to the mud.','clam 作不及物动词，表示挖蛤蜊；for an hour 表时长。','退潮时寻找并挖取双壳贝类体现 clam.s3。'),'The children clammed for an hour by planting tulip bulbs in dry flowerpots.','The children dug for clams for an hour by searching shallow mud at low tide.','采摘花卉与挖蛤蜊是不同活动；修正后保留赶海情境。',[q('clam',1,1,'A clam is a sea animal with?',['two shells','feathers and a beak','a single wooden stem'],'two shells','clam.s1 是可食用的双壳海生动物。'),q('clam',2,2,'Calling someone a clam may suggest that the person?',['says very little','speaks continuously','works as a shellfish farmer'],'says very little','clam.s2 可比喻沉默寡言的人。'),q('clam',3,3,'If a witness clams up, the witness?',['refuses or stops speaking','digs up shellfish','asks loudly for more time'],'refuses or stops speaking','clam up 是闭口不言的习语。'),q('clam',4,1,'Which action means to clam for a living?',['digging edible shellfish from coastal mud','writing a legal citation','measuring a ship’s hatch rim'],'digging edible shellfish from coastal mud','动词 clam.s3 指挖蛤蜊。')]);
put('clamor','clamor 经古法语 clamor 来自拉丁语 clamor（呼喊），可指喧闹的呼声，也可作动词表示大声要求。',c('clamor.s2','公共集会','Parents clamored for safer crossings after a speeding car struck a barrier outside the primary school.','一辆超速汽车撞上小学外的护栏后，家长们大声要求设置更安全的过街设施。','Parents clamored for safer crossings / after a speeding car struck a barrier outside the primary school.','clamored for 是动词短语，表示吵着要求；after 从句交代起因。','群体因担忧而大声要求措施，符合 clamor.s2。'),'The residents clamored quietly for repairs by sending one private note that made no demand.','The residents clamored loudly for repairs at the public meeting.','clamor 作动词表示大声或强烈地要求，私下无声便条不符合。',[q('clamor',1,1,'A clamor in a crowded hall is?',['a loud confused uproar','a quiet written citation','a single musical note'],'a loud confused uproar','clamor.s1 指喧闹或强烈呼声。'),q('clamor',2,2,'To clamor for safer roads is to?',['demand them loudly and insistently','silently accept every risk','measure the width of the road'],'demand them loudly and insistently','clamor.s2 表示大声要求。'),q('clamor',3,1,'Which scene contains a clamor?',['a crowd shouting competing demands','one person reading quietly','an empty room after closing'],'a crowd shouting competing demands','多人嘈杂呼喊构成 clamor。'),q('clamor',4,2,'After the decision, fans clamored for a replay. They?',['noisily insisted on seeing it again','asked politely for a map','cancelled the game without comment'],'noisily insisted on seeing it again','clamor for 表示吵着要求某事。')]);
put('clamorous','clamorous 由 clamor 加形容词后缀 -ous 构成，描述声音喧闹或以吵闹方式提出要求。',c('clamorous.s1','体育赛场','A clamorous crowd filled the station concourse, chanting for the delayed team bus to return before the final match.','喧闹的人群挤满车站大厅，高喊着要求球队大巴在决赛前返回。','A clamorous crowd filled the station concourse / chanting for the delayed team bus to return before the final match.','clamorous 修饰 crowd；现在分词说明人群的吵闹表现。','群体高喊要求，兼有喧闹与吵着索求的特点。'),'The clamorous audience listened in complete silence and made no sound or demand.','The quiet audience listened in complete silence and made no sound or demand.','安静无声与 clamorous“喧闹的”正相反。',[q('clamorous',1,1,'A clamorous crowd is?',['loud and noisy','silent and empty','carefully classified'],'loud and noisy','clamorous.s1 指喧闹的。'),q('clamorous',2,1,'A clamorous appeal for help would be?',['a loud, urgent demand for help','a private note never delivered','a relaxed conversation about music'],'a loud, urgent demand for help','clamorous 也可形容吵闹急切的诉求。'),q('clamorous',3,1,'Which sound is clamorous?',['many people shouting over one another','a single clock ticking in a quiet room','a page turning softly'],'many people shouting over one another','多人嘈杂叫喊体现 clamorous。'),q('clamorous',4,1,'A clamorous protest is likely to?',['make its demands noisily','avoid attracting any attention','take place without participants'],'make its demands noisily','clamorous protest 喧闹并大声提出诉求。')]);
put('clamour','clamour 是 clamor 的英式拼写，名词指嘈杂喧闹声，动词常与 for 连用表示大声要求。',c('clamour.s2','公共交通','Passengers clamoured for an explanation when the station display showed three different departure times for the same train.','车站屏幕给同一趟列车显示了三个不同发车时间，乘客们于是大声要求解释。','Passengers clamoured for an explanation / when the station display showed three different departure times for the same train.','clamoured for 是过去式动词搭配，表示吵着要求。','乘客因信息混乱而强烈索要解释，符合 clamour.s2。'),'Passengers clamoured for an explanation by calmly accepting the contradictory times without speaking.','Passengers asked quietly for an explanation after noticing the contradictory times.','无声接受并非大声要求；修正成礼貌询问，保留索要解释的意思。',[q('clamour',1,1,'The clamour from outside was?',['a loud, confused noise','a carefully footnoted quotation','a gentle breeze'],'a loud, confused noise','clamour.s1 指嘈杂喧闹声。'),q('clamour',2,2,'To clamour for compensation is to?',['demand compensation loudly and strongly','quietly decline any payment','calculate the circumference of a coin'],'demand compensation loudly and strongly','clamour.s2 作动词表示大声要求。'),q('clamour',3,1,'Which sentence uses clamour as a noun?',['A clamour rose from the packed corridor.','They clamoured to enter the hall.','She measured the clamour carefully.'],'A clamour rose from the packed corridor.','这里 clamour 是 rose 的主语，指喧闹声。'),q('clamour',4,2,'The crowd clamoured for water. What did it do?',['shout insistently to demand water','offer water without being asked','turn water into a solid'],'shout insistently to demand water','clamour for 是大声要求某物。')]);
put('clarification','clarification 由 clarify 加名词后缀 -ation 构成，通常指消除疑惑的解释，也可指液体净化澄清的过程。',c('clarification.s2','食品加工','During clarification, the juice passed through a filter that removed suspended pulp and left the liquid visibly clearer.','澄清过程中，果汁经过滤器去除悬浮果肉，液体因此明显变清。','During clarification / the juice passed through a filter / that removed suspended pulp / and left the liquid visibly clearer.','clarification 作过程名词；that 从句修饰 filter。','过滤悬浮颗粒使液体清亮，体现 clarification.s2。'),'Clarification of the juice made it cloudy by adding more suspended pulp.','Clarification of the juice made it clear by removing suspended pulp.','液体澄清是去除颗粒使其清亮，不是增加浑浊物。',[q('clarification',1,1,'A teacher’s clarification should?',['make a confusing point easier to understand','make an already clear point impossible to follow','change a student’s citizenship'],'make a confusing point easier to understand','clarification.s1 是消除疑惑的说明。'),q('clarification',2,2,'In food processing, clarification of juice means?',['removing particles so the liquid becomes clearer','adding pulp until it becomes opaque','freezing the juice into ice'],'removing particles so the liquid becomes clearer','clarification.s2 指净化、澄清液体。'),q('clarification',3,1,'A clarification in a contract might explain?',['what an ambiguous clause means','how to tune a cither','the colour of a fruit peel'],'what an ambiguous clause means','解释含混条款可以澄清其含义。'),q('clarification',4,2,'Which process is liquid clarification?',['filtering suspended matter from broth','stirring sand into clear water','adding ink to make water darker'],'filtering suspended matter from broth','滤除悬浮物可使液体澄清。')]);
put('classical','classical 由 classic 加形容词后缀 -al 构成，可指古希腊罗马文化，也可指公认典范或传统艺术风格。',c('classical.s3','音乐评论','The festival paired a classical string quartet with a contemporary dance piece, though both works drew on the same folk melody.','音乐节把一支古典弦乐四重奏与现代舞作品编在一起，不过两部作品都借用了同一支民歌旋律。','The festival paired a classical string quartet with a contemporary dance piece / though both works drew on the same folk melody.','classical 作定语修饰 string quartet；though 从句补充音乐素材。','传统严肃音乐风格对应 classical.s3。'),'The quartet played classical music by improvising electronic dance beats with no traditional instruments.','The quartet played contemporary electronic music by improvising dance beats with no traditional instruments.','没有传统器乐、改奏电子舞曲不能准确称 classical quartet。',[q('classical',1,1,'Classical Greek art is associated with?',['ancient Greece and Rome','modern computer networks','medieval ship insurance'],'ancient Greece and Rome','classical.s1 指古希腊罗马文化。'),q('classical',2,2,'A classical example of a principle is?',['a recognized, lasting model of it','a recent mistake with no influence','a private letter unrelated to it'],'a recognized, lasting model of it','classical.s2 可表示典范、经典的。'),q('classical',3,3,'A classical string quartet most likely performs?',['traditional serious instrumental music','only spoken comedy','a weather report'],'traditional serious instrumental music','classical.s3 描述传统严肃艺术风格。'),q('classical',4,1,'An essay on classical architecture might discuss?',['columns and temples of ancient Rome','the latest smartphone interface','modern traffic-light timing'],'columns and temples of ancient Rome','古希腊罗马建筑属于 classical.s1。')]);

put('classicism','classicism 由 classical 加 -ism 构成，指古希腊罗马艺术规范的追随，也指对古典范式的推崇。',c('classicism.s2','文学评论','The novelist’s classicism showed in balanced sentences, formal diction, and deliberate references to Greek tragedy.','这位小说家的古典主义体现在匀称的句子、正式措辞以及对希腊悲剧的刻意引用中。','The novelist’s classicism showed in balanced sentences / formal diction / and deliberate references to Greek tragedy.','classicism 作主语；in 后列举其文学风格表现。','推崇并采用古典范式属于 classicism.s2。'),'The painter’s classicism rejected all ancient models and deliberately avoided every classical form.','The painter’s modernism rejected ancient models and deliberately avoided classical forms.','追随古典范式与拒绝古典形式相反，应以 modernism 替换。',[q('classicism',1,1,'Classicism in art generally looks to?',['ancient Greek and Roman models','random modern advertising slogans','scientific weather charts'],'ancient Greek and Roman models','classicism.s1 指遵循古希腊罗马艺术风格。'),q('classicism',2,2,'A writer’s classicism may appear in?',['admiration for ancient literary models','rejection of all inherited forms','a list of citizenship requirements'],'admiration for ancient literary models','classicism.s2 可指对古典作品与规范的推崇。'),q('classicism',3,1,'Which work most clearly shows classicism?',['a sculpture using balanced proportions drawn from Greek models','a sound recording of traffic with no formal design','a recipe for cinnamon tea'],'a sculpture using balanced proportions drawn from Greek models','借鉴希腊比例规范体现古典主义。'),q('classicism',4,2,'Classical restraint in a poem reflects?',['the poet’s adherence to traditional ideals','the poet’s refusal to consider form','the poem’s chemical composition'],'the poet’s adherence to traditional ideals','对传统古典形式的遵循是 classicism 的表现。')]);
put('classification','classification 由 classify 加名词后缀 -ation 构成，指按类别整理的行为，也指分好后所属的类别或等级。',c('classification.s2','档案管理','The museum changed the manuscript’s classification from “local correspondence” to “official record” after finding a government seal.','发现政府印章后，博物馆把这份手稿的分类从“地方通信”改成了“官方档案”。','The museum changed the manuscript’s classification / from “local correspondence” to “official record” / after finding a government seal.','classification 是 changed 的宾语；from…to…标明类别变化。','归档后赋予的类别名称体现 classification.s2。'),'The manuscript’s classification is the act of sorting every document, not the category assigned to this one.','The manuscript’s classification is the category assigned to this document.','此句讨论单份手稿被划入的类别，而非分类这一过程。',[q('classification',1,1,'Classification of a collection is the act of?',['sorting items into groups by type','quoting a passage in an essay','measuring the distance around a circle'],'sorting items into groups by type','classification.s1 指分类行为。'),q('classification',2,2,'A document’s security classification might be?',['the category assigned to it','the clerk’s handwriting style','the number of pages it contains'],'the category assigned to it','classification.s2 指被赋予的类别或级别。'),q('classification',3,1,'Which action is classification?',['grouping minerals according to their properties','reading a single poem aloud','replacing a clock’s battery'],'grouping minerals according to their properties','按性质分组就是进行分类。'),q('classification',4,2,'If a file is given a new classification, it receives?',['a different assigned category','a new author automatically','a different language alphabet'],'a different assigned category','这里 classification 是所归属的类别。')]);
put('classified','classified 是 classify 的过去分词形容词，可指已经分类的事物，也可指官方定为机密、限制查阅的信息。',c('classified.s2','政府档案','The clerk stored the classified report in a locked cabinet and logged every person who was authorised to read it.','职员把机密报告存入上锁的柜子，并登记了每一位获准阅读的人。','The clerk stored the classified report in a locked cabinet / and logged every person / who was authorised to read it.','classified 修饰 report；who 从句限定获准人员。','限制查阅的官方机密文件对应 classified.s2。'),'The classified report was posted publicly online for anyone to read without restriction.','The public report was posted online for anyone to read without restriction.','公开且不受限制的材料不是 classified 机密文件。',[q('classified',1,1,'A classified list of specimens has been?',['arranged into categories','kept secret by a government necessarily','destroyed before examination'],'arranged into categories','classified.s1 指已经分类的。'),q('classified',2,2,'A classified military report is?',['officially secret or access-restricted','sorted alphabetically only','printed on unusually large paper'],'officially secret or access-restricted','classified.s2 指被定为机密。'),q('classified',3,1,'A librarian’s classified catalogue is one whose entries are?',['grouped by subject or type','hidden from all library workers','written only in code'],'grouped by subject or type','分类目录按主题或类别整理。'),q('classified',4,2,'Why might access to classified information be limited?',['it is officially designated secret','it is a public recipe for bread','it is printed in alphabetical order'],'it is officially designated secret','官方机密信息只准授权人员查阅。')]);
put('clavichord','clavichord 由拉丁语 clavis（键）与 chorda（弦）构成，指键击式古键盘乐器，键端的金属切线触弦发声。',c('clavichord.s1','早期音乐','The musician played the clavichord softly in the small gallery, where its delicate tone could be heard without competing with conversation.','音乐家在小展厅里轻轻弹奏击弦古钢琴；这种乐器音色细弱，不会盖过谈话声。','The musician played the clavichord softly in the small gallery / where its delicate tone could be heard / without competing with conversation.','clavichord 是 played 的宾语；where 从句补充演奏环境。','键盘演奏、音量柔和的早期弦乐器符合 clavichord.s1。'),'The clavichord produces its sound when a player blows air through a brass mouthpiece.','The clavichord produces its sound when keyboard tangents strike its strings.','clavichord 是击弦键盘乐器，不是吹奏铜管乐器。',[q('clavichord',1,1,'A clavichord produces notes when?',['keyboard tangents strike its strings','air passes through a brass mouthpiece','a drumhead is shaken'],'keyboard tangents strike its strings','clavichord.s1 是切线击弦式键盘乐器。'),q('clavichord',2,1,'Which family best describes the clavichord?',['early keyboard string instrument','brass wind instrument','frame drum'],'early keyboard string instrument','它有键盘，靠击弦发声。'),q('clavichord',3,1,'Why might a clavichord suit a small room?',['its sound is quiet and delicate','it produces the loudest orchestral sound','it has no strings or keys'],'its sound is quiet and delicate','clavichord 以音量柔和著称。'),q('clavichord',4,1,'A museum visitor should expect to see?',['a historical keyboard with strings','a metal trumpet with valves','a pair of scissors'],'a historical keyboard with strings','clavichord 是古老的键盘弦乐器。')]);
put('clayware','clayware 由 clay 与 ware（制品、器皿）组合而成，指用黏土塑形并通常经烧制制成的陶器。',c('clayware.s1','手工陶艺','The village workshop displayed clayware bowls beside the kiln, each marked with the potter’s initials and firing date.','村里的作坊把陶碗陈列在窑旁，每件都标有陶工姓名首字母和烧制日期。','The village workshop displayed clayware bowls beside the kiln / each marked with the potter’s initials and firing date.','clayware 修饰 bowls；each marked 是补充说明每只碗的分词结构。','由黏土制成并烧制的碗是 clayware。'),'The shop labelled its clayware as items carved entirely from solid steel.','The shop labelled its steelware as items made entirely from solid steel.','clayware 应由黏土制成；纯钢制品应称 steelware。',[q('clayware',1,1,'Clayware consists of objects made from?',['clay, often shaped and fired','woven metal wire','solid ice'],'clay, often shaped and fired','clayware.s1 指黏土制品，常为陶器。'),q('clayware',2,1,'Which item could be clayware?',['a fired earthenware bowl','a stainless-steel spoon','a cotton scarf'],'a fired earthenware bowl','烧制黏土碗属于 clayware。'),q('clayware',3,1,'A potter making clayware will normally work with?',['mouldable clay and a kiln','a loom and yarn','a compass and ink only'],'mouldable clay and a kiln','陶器先用黏土成形，通常再烧制。'),q('clayware',4,1,'The suffix “-ware” in clayware points to?',['articles or goods of a material','the colour of a gemstone','a person’s legal status'],'articles or goods of a material','ware 表示器物、制品。')]);
put('cleanly','cleanly 由 clean 加 -ly 构成；作形容词指个人或环境习惯清洁，作副词可指利落、彻底而无残留地完成动作。',c('cleanly.s2','木工操作','The sharp plane sliced cleanly through the pine, leaving a smooth edge with no splinters or torn fibres.','锋利的刨子利落地刨过松木，留下光滑边缘，没有木刺或撕裂的纤维。','The sharp plane sliced cleanly through the pine / leaving a smooth edge / with no splinters or torn fibres.','cleanly 修饰 sliced，说明切削平整彻底。','动作干净利落、无毛边对应 cleanly.s2。'),'The blade cut cleanly by tearing the board into ragged fibres and leaving splinters everywhere.','The blade cut roughly by tearing the board into ragged fibres and leaving splinters everywhere.','遍布毛刺、木纤维撕裂是 rough cut，不是 cleanly。',[q('cleanly',1,1,'A cleanly kept home is?',['habitually neat and hygienic','always covered in dust','built only from white stone'],'habitually neat and hygienic','cleanly.s1 作形容词时指爱清洁、保持整洁。'),q('cleanly',2,2,'If a branch breaks cleanly, it breaks?',['smoothly, without ragged edges','into a tangled mass of fibres','without breaking at all'],'smoothly, without ragged edges','cleanly.s2 指动作利落、没有凌乱残留。'),q('cleanly',3,1,'Which person is described as cleanly?',['someone who regularly keeps their clothes and room clean','someone who deliberately spills paint everywhere','someone who never washes'],'someone who regularly keeps their clothes and room clean','习惯整洁的人可称 cleanly。'),q('cleanly',4,2,'A runner crossed the finish line cleanly. This suggests the runner?',['completed the move decisively and without mishap','left a messy collision behind','forgot to reach the line'],'completed the move decisively and without mishap','副词 cleanly 可表示利落、顺畅地完成动作。')]);
put('cleave','cleave 有两个不同古英语来源：clēofan“劈开”和 clifian“黏附”；因此它既可指分裂，也可指紧密依附。',c('cleave.s2','历史文献','Despite pressure from the court, the small community continued to cleave to its language and oral traditions.','尽管受到朝廷压力，这个小社群仍坚持依附自己的语言和口述传统。','Despite pressure from the court / the small community continued to cleave to its language and oral traditions.','cleave to 是动词搭配，to 后接依附的对象。','持续忠于某种语言传统，体现 cleave.s2 的依附义。'),'The community cleaved to its traditions by abandoning them completely and refusing to remember them.','The community departed from its traditions by abandoning them completely.','完全抛弃传统并非 cleave to；depart from 表达相反意思。',[q('cleave',1,1,'To cleave a log with an axe is to?',['split it apart','polish it until it shines','tie it to another log'],'split it apart','cleave.s1 是用力劈开或裂开。'),q('cleave',2,2,'To cleave to a principle is to?',['remain faithful to it','cut it into pieces','measure its circumference'],'remain faithful to it','cleave.s2 指紧密依附、坚持或忠于。'),q('cleave',3,1,'Which action cleaves a block of wood?',['striking it so it splits into two','gluing two unbroken blocks together','painting its surface blue'],'striking it so it splits into two','劈裂木块体现第一义。'),q('cleave',4,2,'A family may cleave to a custom by?',['continuing to observe and value it','discarding it as soon as it is taught','cutting the custom from a sheet of paper'],'continuing to observe and value it','cleave to 表示忠于、坚持某习俗。')]);
put('clef','clef 经法语来自拉丁语 clavis（钥匙），在乐谱中指确定五线谱各线音高的谱号。',c('clef.s1','读谱训练','Because the melody moved into a lower register, the arranger changed the clef at the start of the staff before copying the notes.','由于旋律转入较低音区，编曲者在抄写音符前更换了五线谱开头的谱号。','Because the melody moved into a lower register / the arranger changed the clef at the start of the staff / before copying the notes.','clef 是 changed 的宾语；at the start of the staff 指其谱面位置。','改变谱号以重新确定五线谱音高对应关系，符合 clef.s1。'),'The clef at the beginning of the staff tells the reader the page’s paper size.','The clef at the beginning of the staff tells the reader how the staff’s pitches are assigned.','谱号确定音高，不决定纸张大小。',[q('clef',1,1,'A clef on a musical staff tells the reader?',['which pitches the lines represent','how long the page is','which instrument is made of clay'],'which pitches the lines represent','clef.s1 是确定五线谱音高的记号。'),q('clef',2,1,'Where is a clef usually written?',['at the beginning of a staff','on the back of a concert ticket','inside a drum shell'],'at the beginning of a staff','谱号通常置于五线谱开头。'),q('clef',3,1,'Changing a clef can change how the reader interprets?',['the pitches assigned to the staff lines','the colour of the printed ink only','the number of audience seats'],'the pitches assigned to the staff lines','谱号决定线与音高的映射。'),q('clef',4,1,'Which is a musical clef?',['treble clef','circumference clef','citizenship clef'],'treble clef','treble clef 是常见谱号。')]);
put('cleft','cleft 是 cleave（劈开）的过去分词形式，可作名词指裂口，也可作形容词描述裂开的状态。',c('cleft.s1','地貌考察','The hikers squeezed through a narrow cleft in the limestone ridge, where rainwater had widened the opening over centuries.','徒步者挤过石灰岩山脊上一道狭窄裂缝，雨水历经数百年把开口冲宽。','The hikers squeezed through a narrow cleft in the limestone ridge / where rainwater had widened the opening over centuries.','cleft 是介词 through 的宾语；where 从句补充裂口形成背景。','岩石中的狭窄裂隙体现 cleft.s1。'),'The hikers crossed a cleft that was a smooth, unbroken field with no opening.','The hikers crossed a plain that was a smooth, unbroken field with no opening.','没有裂口的完整平地不是 cleft；plain 符合修正描述。',[q('cleft',1,1,'A cleft in a rock face is?',['a narrow split or opening','a smooth, unbroken surface','a musical pitch symbol'],'a narrow split or opening','cleft.s1 指裂缝或裂口。'),q('cleft',2,2,'A cleft chin is a chin that is?',['split or indented down the middle','perfectly flat with no division','covered with a musical staff'],'split or indented down the middle','身体上的凹裂也属于 cleft 的形容义。'),q('cleft',3,1,'Which scene contains a cleft?',['a deep fissure in a cliff after rockfall','an unbroken sandy beach','a tree with no split or scar'],'a deep fissure in a cliff after rockfall','悬崖上的裂隙符合名词 cleft。'),q('cleft',4,2,'“A cleft surface” means the surface is?',['split or partly divided','perfectly seamless','made of citrus peel'],'split or partly divided','cleft.s2 表示劈开或裂开的。')]);
put('clement','clement 经古法语来自拉丁语 clemens（温和、仁慈），可形容不恶劣的天气，也可形容宽厚仁慈的人。',c('clement.s2','司法叙事','The judge was clement toward the first-time offender, choosing a warning and community service instead of a long prison term.','法官对初犯者宽大处理，选择警告和社区服务，而不是长期监禁。','The judge was clement toward the first-time offender / choosing a warning and community service / instead of a long prison term.','clement 作表语，toward 引出宽待对象；现在分词说明处理方式。','减轻处罚、表现宽恕体现 clement.s2。'),'The judge was clement by imposing the harshest possible sentence for a minor first offense.','The judge was severe by imposing the harshest possible sentence for a minor first offense.','最严厉的处罚表现严厉而非宽大仁慈。',[q('clement',1,1,'Clement weather is?',['mild and pleasant','violent and stormy','extremely cold and dangerous'],'mild and pleasant','clement.s1 指温和宜人的天气。'),q('clement',2,2,'A clement ruler is one who?',['shows mercy when punishing','punishes every person without exception','studies weather maps'],'shows mercy when punishing','clement.s2 描述仁慈宽厚。'),q('clement',3,1,'Which forecast describes clement conditions?',['light winds and mild temperatures','a severe blizzard and dangerous ice','a destructive cyclone'],'light winds and mild temperatures','天气温和、不恶劣符合 clement。'),q('clement',4,2,'A clement judge might?',['reduce a sentence out of mercy','increase punishment without considering the case','measure a defendant’s height'],'reduce a sentence out of mercy','仁慈法官可能酌情从宽。')]);

put('clientele','clientele 经法语来自 client，最终源自拉丁语 cliens（受庇护者、依附者），指某商店或专业人士的顾客群。',c('clientele.s1','商业经营','The café built a loyal clientele by remembering regular customers’ orders and keeping the same early opening hours through winter.','这家咖啡馆靠记住常客的点单、冬天也照常早开门，建立了一群忠实顾客。','The café built a loyal clientele / by remembering regular customers’ orders / and keeping the same early opening hours through winter.','clientele 是 built 的宾语；by 后的并列动名词说明经营方式。','经常光顾同一家店的客户群是 clientele.s1。'),'The bakery’s clientele means a single loaf of bread left unsold on the counter.','The bakery’s clientele means the group of people who regularly buy from it.','clientele 指顾客群，不指一件商品。',[q('clientele',1,1,'A shop’s clientele is?',['the people who regularly use or buy from it','its shelves and lighting','a list of suppliers only'],'the people who regularly use or buy from it','clientele.s1 指某商家的顾客群。'),q('clientele',2,1,'A lawyer with a large clientele has?',['many clients','many courtrooms','many legal dictionaries'],'many clients','clientele 来自 client，指一群客户。'),q('clientele',3,1,'Which group is a theatre’s clientele?',['the regular people who attend its performances','the actors’ costumes','the building’s seats'],'the regular people who attend its performances','常来观看演出的观众构成其顾客群。'),q('clientele',4,1,'A business tries to retain its clientele by?',['serving its regular customers well','closing before every customer arrives','removing every service it offers'],'serving its regular customers well','维护常客关系有助留住 clientele。')]);
put('climacteric','climacteric 源自希腊语 klimaktēr（人生的关键阶段），名词可指更年期或重大转折期，形容词则表示处于关键阶段的。',c('climacteric.s1','医学科普','During the climacteric, some people experience changes in sleep and temperature regulation, so clinicians discuss symptoms individually.','在更年期阶段，有些人会出现睡眠和体温调节变化，因此临床人员会逐一讨论症状。','During the climacteric / some people experience changes in sleep and temperature regulation / so clinicians discuss symptoms individually.','climacteric 作介词 during 的宾语，指一段人生阶段。','上下文围绕更年期相关变化，符合 climacteric.s1。'),'Her climacteric was a daily weather forecast with no relation to a stage of life.','Her climate report was a daily weather forecast with no relation to a stage of life.','天气预报是 climate report；climacteric 指关键人生阶段，尤指更年期。',[q('climacteric',1,1,'The climacteric most specifically refers to?',['the period of menopause','a daily weather bulletin','a musical instrument'],'the period of menopause','climacteric.s1 尤指更年期。'),q('climacteric',2,1,'Outside medicine, a climacteric can be?',['a decisive turning point in life','a small routine adjustment','a type of stone wall'],'a decisive turning point in life','该词也指人生重大转折阶段。'),q('climacteric',3,2,'A climacteric decision is one made?',['at a critical turning point','without any consequence','only during rainy weather'],'at a critical turning point','climacteric.s2 作形容词指关键或转折阶段的。'),q('climacteric',4,1,'Which subject might a health guide discuss under “the climacteric”?',['menopause and related life-stage changes','how to tune a clavichord','how to cite a journal article'],'menopause and related life-stage changes','climacteric 常用于更年期语境。')]);
put('climatic','climatic 由 climate 加形容词后缀 -ic 构成，可指气候本身，也可表示由气候造成或影响的。',c('climatic.s2','农业生产','The region’s climatic conditions caused the harvest to fail: an unusually long drought left the fields too dry for young plants.','该地区的气候条件导致歉收：异常漫长的干旱使田地干到幼苗无法生长。','The region’s climatic conditions caused the harvest to fail / an unusually long drought left the fields too dry for young plants.','climatic 修饰 conditions；冒号后的分句说明气候造成的结果。','干旱使收成受损，突出 climatic.s2“由气候导致”。'),'The climatic damage to the crop was caused by a broken warehouse door, not by weather.','The storage damage to the crop was caused by a broken warehouse door, not by weather.','仓库门损坏不是气候因素；storage damage 才符合此原因。',[q('climatic',1,1,'A climatic pattern concerns?',['the usual weather conditions of a region','the language used in a court','the structure of a musical chord'],'the usual weather conditions of a region','climatic.s1 指与地区气候有关。'),q('climatic',2,2,'Climatic damage to crops is damage?',['caused by climate or weather conditions','caused by an incorrectly cited source','caused by a musical performance'],'caused by climate or weather conditions','climatic.s2 表示由气候引起。'),q('climatic',3,1,'A researcher comparing climatic zones would compare?',['long-term weather conditions in different areas','the seating plans of cinemas','the legal status of residents'],'long-term weather conditions in different areas','气候区按较长期的天气条件区分。'),q('climatic',4,2,'A climatic cause of drought-related crop failure is?',['a prolonged lack of rainfall','a mislabeled museum exhibit','a broken musical string'],'a prolonged lack of rainfall','缺雨属于气候条件并可导致歉收。')]);
put('climatically','climatically 由 climatic 加副词后缀 -ally 构成，表示从气候角度看，或由于气候条件而发生。',c('climatically.s1','区域规划','The two valleys are climatically distinct: one receives steady coastal rain, while the other stays dry behind the mountain ridge.','两个山谷的气候差异明显：一个持续受沿海降雨影响，另一个则被山脊挡住水汽而保持干燥。','The two valleys are climatically distinct / one receives steady coastal rain / while the other stays dry behind the mountain ridge.','climatically 修饰形容词 distinct；冒号后举例说明差异。','按气候角度比较两个山谷，符合 climatically.s1。'),'The islands are climatically different because one has a larger library and more books.','The islands are culturally different because one has a larger library and more books.','图书馆和书籍体现文化差异，不是气候差异。',[q('climatically',1,1,'If two regions differ climatically, they differ in?',['their climate','their legal systems','their musical instruments'],'their climate','climatically.s1 指在气候方面。'),q('climatically',2,1,'A town climatically suited to olives has?',['weather conditions favourable to olive growing','a population that rejects olive trees','a legal ban on farming'],'weather conditions favourable to olive growing','副词说明适合种植的气候条件。'),q('climatically',3,1,'Which comparison is climatic?',['contrasting rainfall and temperatures between valleys','comparing the valleys’ school uniforms','counting the number of street lamps'],'contrasting rainfall and temperatures between valleys','降雨量和温度属于气候特征。'),q('climatically',4,1,'A climatically harsh winter is harsh because of?',['severe weather conditions','a strict court ruling','a noisy audience'],'severe weather conditions','气候恶劣指天气条件严酷。')]);
put('clinch','clinch 与 clench 有历史关联，早期拼写和词源细节不确定；现代动词常指最终敲定或制胜，名词也指拳击中的贴身扭抱。',c('clinch.s1','竞赛报道','The visiting team clinched the championship when its captain scored in the final minute of the last match.','客队队长在最后一场比赛的最后一分钟得分，帮助球队锁定冠军。','The visiting team clinched the championship / when its captain scored in the final minute of the last match.','clinch 直接带宾语 championship；when 从句说明决定性时刻。','关键得分使冠军胜局确定，符合 clinch.s1。'),'The team clinched the championship but the title remained undecided after the final match.','The team clinched the championship and the title was decided after the final match.','clinch 表示一举确定结果；仍未决定与此义相反。',[q('clinch',1,1,'To clinch a deal is to?',['settle it finally','postpone every decision','measure the cost of a ticket'],'settle it finally','clinch.s1 表示最终敲定。'),q('clinch',2,2,'In boxing, a clinch is?',['a close hold that limits punching','a referee’s written citation','a long-distance running race'],'a close hold that limits punching','clinch.s2 指拳击中贴身抱住对手。'),q('clinch',3,1,'A late goal clinched the match. It?',['secured the victory decisively','made the result less certain','cancelled the match before play'],'secured the victory decisively','决定性进球锁定了胜局。'),q('clinch',4,2,'Why might a referee separate boxers in a clinch?',['they are holding each other close and cannot punch freely','they are standing on opposite sides of the ring','they are writing down the score'],'they are holding each other close and cannot punch freely','拳击搂抱会限制双方出拳。')]);
put('clipper','clipper 由 clip 加表示工具或施动者的 -er 构成，指剪切工具；历史上也指以速度见长的帆船。',c('clipper.s2','航海史','The clipper crossed the ocean quickly under a full spread of canvas, carrying tea from the port before slower ships arrived.','这艘快速帆船扬起全部帆布迅速横渡海洋，在较慢的船只抵达前把茶叶运到港口。','The clipper crossed the ocean quickly under a full spread of canvas / carrying tea from the port / before slower ships arrived.','clipper 作主语；carrying 分词说明其货运任务。','十九世纪以速度著称的帆船对应 clipper.s2。'),'The nineteenth-century clipper crossed the ocean using a steam turbine and no sails.','The nineteenth-century steamship crossed the ocean using a turbine and no sails.','历史 clipper 是帆船，使用蒸汽涡轮的应称 steamship。',[q('clipper',1,1,'Hair clippers are?',['tools for cutting hair','tools for measuring rainfall','musical instruments with strings'],'tools for cutting hair','clipper.s1 指剪切工具，常用复数 clippers。'),q('clipper',2,2,'A nineteenth-century clipper was known as?',['a fast sailing ship','a slow river barge','a steam locomotive'],'a fast sailing ship','clipper.s2 指快速帆船。'),q('clipper',3,1,'Which item might a barber use clippers for?',['trimming hair','printing a citation','measuring a ship’s hull'],'trimming hair','理发器是 clipper 的工具义。'),q('clipper',4,2,'A tea clipper would historically carry tea by?',['sailing quickly across the sea','flying between airports','travelling through a pipeline'],'sailing quickly across the sea','快速帆船承担远洋货运。')]);
put('cloakroom','cloakroom 由 cloak 与 room 组合而成，指公共建筑内寄存外套和行李的房间；英式英语中也可委婉指洗手间。',c('cloakroom.s2','公共设施','The theatre usher pointed visitors toward the cloakroom when a guest asked where the public toilets were.','一位观众询问公共洗手间在哪里时，剧院引座员把他们指向了洗手间。','The theatre usher pointed visitors toward the cloakroom / when a guest asked where the public toilets were.','cloakroom 是 toward 的宾语；where 从句说明观众问的地点。','英式英语以 cloakroom 委婉指公共厕所，符合 s2。'),'In this British theatre, the cloakroom was where visitors went to leave their coats, not to use the toilet.','In this British theatre, the cloakroom was the public toilet, not the coat-storage room.','英式英语该义项可指洗手间；原句的否定与此冲突。',[q('cloakroom',1,1,'A theatre cloakroom commonly lets visitors?',['leave coats and bags temporarily','buy a house','tune a clavichord'],'leave coats and bags temporarily','cloakroom.s1 是衣帽及行李寄存处。'),q('cloakroom',2,2,'In British usage, asking for the cloakroom may mean asking for?',['a public toilet','the orchestra pit','the ticket office'],'a public toilet','cloakroom.s2 是英式英语对洗手间的委婉说法。'),q('cloakroom',3,1,'A coat-check attendant usually works in the?',['cloakroom','citadel','engine room'],'cloakroom','寄存外套通常在衣帽间办理。'),q('cloakroom',4,2,'A British sign reading “Ladies’ cloakroom” points to?',['a women’s toilet','a room for storing winter coats only','a room where films are photographed'],'a women’s toilet','英式公共场所常用 cloakroom 指洗手间。')]);
put('clockmaker','clockmaker 由 clock 与 maker 构成，指以制造或修理钟表为职业的人。',c('clockmaker.s1','手工行业','The clockmaker removed the brass hands, cleaned the escapement, and tested the mechanism before returning the wall clock to its owner.','钟表匠卸下黄铜指针，清洁擒纵机构，并在把挂钟还给主人前测试机芯。','The clockmaker removed the brass hands / cleaned the escapement / and tested the mechanism / before returning the wall clock to its owner.','clockmaker 是动作的施事主语；并列动词列出修理步骤。','修理挂钟机芯是钟表匠的工作。'),'The clockmaker repaired the wall clock by baking bread and never touching its mechanism.','The baker made bread while the clockmaker repaired the wall clock mechanism.','烘焙是面包师的工作；clockmaker 制作或修理钟表。',[q('clockmaker',1,1,'A clockmaker’s trade is?',['making or repairing clocks','classifying ancient pottery','conducting a courtroom trial'],'making or repairing clocks','clockmaker.s1 指制钟或修钟的人。'),q('clockmaker',2,1,'Who would inspect a clock’s escapement?',['a clockmaker','a pastry chef','a ship’s passenger'],'a clockmaker','擒纵机构是钟表机芯的一部分。'),q('clockmaker',3,1,'A clockmaker repairing a wall clock might?',['clean its mechanism and adjust its hands','change the weather forecast','cut a circle from cloth'],'clean its mechanism and adjust its hands','维修钟表通常包括清洁机芯和调整指针。'),q('clockmaker',4,1,'The compound clockmaker names?',['a person by their craft','a clock’s circumference','a type of public room'],'a person by their craft','maker 表示制作或修理该物件的人。')]);
put('clod','clod 源自古英语 clod（泥土块），名词也可口语贬称迟钝笨拙的人。',c('clod.s2','人物对白','“Don’t be such a clod,” Mara said when he walked past the clearly marked exit and blamed the locked door.','他从标得很清楚的出口旁走过，还责怪门锁着，玛拉便说：“别这么笨了。”','“Don’t be such a clod,” Mara said / when he walked past the clearly marked exit / and blamed the locked door.','clod 作 be 的表语，口语中贬指笨拙迟钝的人。','对白以 clod 形容犯糊涂的人，符合 clod.s2。'),'He was called a clod because he solved every puzzle instantly and noticed every detail.','He was called clever because he solved every puzzle instantly and noticed every detail.','反应敏捷、观察细致与 clod 的贬义相反。',[q('clod',1,1,'A clod of earth is?',['a lump of soil','a polished silver spoon','a stringed instrument'],'a lump of soil','clod.s1 指一块泥土。'),q('clod',2,2,'Calling someone a clod is calling them?',['stupid or awkward','exceptionally courteous','a professional clockmaker'],'stupid or awkward','clod.s2 是口语中对笨人的贬称。'),q('clod',3,1,'After ploughing, a farmer might break apart each?',['clod of soil','clef on a staff','citation in a book'],'clod of soil','翻耕后常需打碎土块。'),q('clod',4,2,'Which dialogue uses clod figuratively?',['“You forgot the map again, you clod.”','“The clod crumbled into damp earth.”','“She cited the source in a footnote.”'],'“You forgot the map again, you clod.”','直接称人 clod 时指笨蛋。')]);
put('close-up','close-up 由 close 与 up 组合形成电影摄影术语，指近距离拍摄、细节占满画面的镜头，也可指细看或详细检查。',c('close-up.s1','电影摄影','The director cut to a close-up of the cracked watch face so viewers could see the tiny inscription beside the stopped hands.','导演切换到破裂表盘的特写镜头，让观众看清停住的指针旁那行小字。','The director cut to a close-up of the cracked watch face / so viewers could see the tiny inscription / beside the stopped hands.','close-up 是介词 to 的宾语；so 从句说明特写的目的。','让细小刻字充满画面的近景镜头符合 close-up.s1。'),'The film’s close-up showed the whole mountain range from several miles away with no details visible.','The film’s long shot showed the whole mountain range from several miles away with no details visible.','远距离呈现全景应是 long shot，而不是 close-up。',[q('close-up',1,1,'A film close-up typically shows?',['a subject from very near, with detail filling the frame','an entire landscape from far away','the film’s credits only'],'a subject from very near, with detail filling the frame','close-up.s1 指近距离拍摄的特写。'),q('close-up',2,2,'A close-up examination of a document is?',['a detailed inspection','a distant glance from across the street','a public award'],'a detailed inspection','close-up.s2 可比喻细看、详细检查。'),q('close-up',3,1,'Why use a close-up of a watch dial?',['to make tiny markings visible to viewers','to hide every detail from the audience','to show a different city’s skyline'],'to make tiny markings visible to viewers','特写便于呈现很小的细节。'),q('close-up',4,1,'Which shot is most likely a close-up?',['a face filling most of the screen','a tiny person in a vast landscape','an aerial view of an entire country'],'a face filling most of the screen','主体近距离占据画面是 close-up。')]);

put('closed-circuit','closed-circuit 由 closed 与 circuit 构成，描述信号只在限定线路或接收端之间传送、不向公众广播的系统。',c('closed-circuit.s1','安保系统','The museum installed closed-circuit cameras that sent images only to the security room, rather than broadcasting footage to the public.','博物馆安装了闭路摄像系统，画面只传到安保室，而不向公众广播。','The museum installed closed-circuit cameras / that sent images only to the security room / rather than broadcasting footage to the public.','closed-circuit 作定语修饰 cameras；that 从句说明传输范围。','影像限定传输到特定接收端，体现闭路系统。'),'The closed-circuit camera broadcast its footage to every television channel without restriction.','The public-broadcast camera sent its footage to every television channel without restriction.','closed-circuit 系统限制接收范围，面向所有频道公开广播则不是闭路。',[q('closed-circuit',1,1,'Closed-circuit television sends signals?',['to a limited set of receivers','to the entire public broadcast network','only to the camera operator’s eyes'],'to a limited set of receivers','closed-circuit.s1 指信号只传给限定接收端。'),q('closed-circuit',2,1,'A closed-circuit security system is often used to?',['monitor a building privately','broadcast a live program nationally','play music through a street loudspeaker'],'monitor a building privately','受限传输常用于建筑安保监控。'),q('closed-circuit',3,1,'What distinguishes closed-circuit video from public broadcasting?',['its audience is restricted to connected receivers','it contains no moving pictures','it can only show old films'],'its audience is restricted to connected receivers','闭路影像不向公众广播。'),q('closed-circuit',4,1,'A hospital sends camera feeds only to its security desk. This is?',['a closed-circuit system','an open public broadcast','a printed citation'],'a closed-circuit system','信号只送至指定安保台，符合 closed-circuit。')]);
put('closeness','closeness 由 close 加名词后缀 -ness 构成，可指空间距离近、关系亲密，也可指结果或数值接近。',c('closeness.s1','人际关系','Their closeness grew during the long evacuation, as the neighbours shared food, checked on one another, and made decisions together.','漫长的撤离期间，邻居们分享食物、彼此照应并共同决策，他们的关系也因此更加亲密。','Their closeness grew during the long evacuation / as the neighbours shared food / checked on one another / and made decisions together.','closeness 是 grew 的主语；as 从句说明亲密关系如何形成。','互助和共同经历促成人际亲密，体现 closeness.s1。'),'The closeness between the friends vanished because they lived far apart in every emotional and social sense.','The distance between the friends increased because they lived far apart emotionally and socially.','题干声称关系疏远，不能称为亲密；distance 才符合语意。',[q('closeness',1,1,'Closeness between friends usually means?',['a strong, intimate relationship','a formal legal citation','a large physical separation'],'a strong, intimate relationship','closeness.s1 指情感亲密。'),q('closeness',2,1,'The closeness of two houses refers to?',['their nearness in space','their shared legal owner necessarily','their colour and age'],'their nearness in space','closeness 也指空间距离接近。'),q('closeness',3,1,'A close election result has closeness in?',['the small difference between the candidates’ totals','the distance to the nearest coastline','the age of the voters'],'the small difference between the candidates’ totals','结果接近可用 closeness 表达。'),q('closeness',4,1,'What could increase a team’s closeness?',['shared work and mutual support','members refusing to communicate','splitting the team into unrelated groups'],'shared work and mutual support','共同协作与互助能加强团队亲密和凝聚。')]);
put('clot','clot 词源可能与古英语 clott（块、团）有关；名词指凝块，尤其血块，动词指液体变稠凝结。',c('clot.s1','急救常识','A blood clot formed in the small cut and slowed the bleeding while the nurse cleaned the surrounding skin.','小伤口处形成了血块，在护士清洁周围皮肤时减缓了出血。','A blood clot formed in the small cut / and slowed the bleeding / while the nurse cleaned the surrounding skin.','clot 作名词作主语；formed 表示凝块形成。','伤口处凝结的血团是 clot.s1。'),'A blood clot is a thin gas that flows freely through a vein without forming a mass.','A blood clot is a thickened mass of blood that can form inside a vessel or wound.','血凝块是凝结成团的血液，不是气体。',[q('clot',1,1,'A blood clot is?',['a thickened mass of blood','a clear gas in the lungs','a musical symbol'],'a thickened mass of blood','clot.s1 指液体形成的凝块，尤指血块。'),q('clot',2,2,'If cream clots, it?',['forms thick lumps','becomes a thin invisible gas','turns into a solid metal'],'forms thick lumps','clot.s2 作动词指凝结成团。'),q('clot',3,3,'In informal speech, calling someone a clot means?',['calling them stupid','calling them a medical doctor','calling them a ship captain'],'calling them stupid','clot.s3 可口语贬指笨人。'),q('clot',4,2,'Which liquid may clot?',['blood after coagulation begins','dry sand in a sealed jar','a metal key at room temperature'],'blood after coagulation begins','血液可凝结形成 clot。')]);
put('cloudburst','cloudburst 由 cloud 与 burst 组合而成，指短时间内突然降下的大量暴雨。',c('cloudburst.s1','山地天气','A sudden cloudburst flooded the mountain path, forcing the hikers to shelter beneath a rocky overhang until the water drained away.','突如其来的倾盆大雨淹没了山路，徒步者只得躲在岩石突出部下，直到积水退去。','A sudden cloudburst flooded the mountain path / forcing the hikers to shelter beneath a rocky overhang / until the water drained away.','cloudburst 作主语；forcing 分词说明暴雨导致的后果。','突然短时的大量降雨导致道路积水，符合 cloudburst.s1。'),'The cloudburst brought months of gentle drizzle spread evenly across the region.','The seasonal rainfall brought months of gentle drizzle spread evenly across the region.','持续数月的毛毛雨不是突然短时发生的 cloudburst。',[q('cloudburst',1,1,'A cloudburst is?',['a sudden, very heavy fall of rain','a long period with no rain','a light snowfall lasting all winter'],'a sudden, very heavy fall of rain','cloudburst.s1 指短时倾盆大雨。'),q('cloudburst',2,1,'Which event is a cloudburst?',['intense rain starts abruptly and floods a street','a region receives light rain every Tuesday','a cloud slowly disappears at sunset'],'intense rain starts abruptly and floods a street','骤然强降雨并非稳定的小雨。'),q('cloudburst',3,1,'After a cloudburst, a dry streambed may?',['fill rapidly with water','freeze solid in midsummer without cold','turn into a paved road'],'fill rapidly with water','短时大量降雨可能使沟道迅速积水。'),q('cloudburst',4,1,'The word cloudburst suggests?',['a sudden release of a great deal of rain','a cloud made of stone','a quiet break between two lessons'],'a sudden release of a great deal of rain','cloudburst 是突然爆发的大雨。')]);
put('cloudlike','cloudlike 由 cloud 与 -like（像……的）构成，形容外观、触感或形态像云一样柔软轻盈的。',c('cloudlike.s1','纺织品说明','The quilt felt cloudlike against the child’s skin, yet its dense filling kept her warm through the cold night.','这床被子贴着孩子的皮肤感觉像云一样轻柔，但厚实的填充物让她在寒夜里保持温暖。','The quilt felt cloudlike against the child’s skin / yet its dense filling kept her warm through the cold night.','cloudlike 作表语；yet 对比轻柔触感和保暖效果。','像云般柔软轻盈的触感符合 cloudlike.s1。'),'The cloudlike pillow felt like a solid block of rough iron with sharp edges.','The iron block felt like a solid mass with a rough surface and sharp edges.','坚硬粗糙的铁块与云般柔软轻盈不相符。',[q('cloudlike',1,1,'A cloudlike cushion would probably feel?',['soft and light','heavy and jagged','sharp and metallic'],'soft and light','cloudlike.s1 表示像云一样轻柔。'),q('cloudlike',2,1,'A cloudlike shape in the sky might be?',['soft and puffy in appearance','a perfectly straight metal rod','a flat sheet of glass'],'soft and puffy in appearance','形状像云可指蓬松柔和。'),q('cloudlike',3,1,'Which description fits cloudlike fabric?',['airy and soft to the touch','stiff like a steel plate','wet and granular like gravel'],'airy and soft to the touch','轻盈柔软是常见的 cloudlike 质感。'),q('cloudlike',4,1,'Why call a pillow cloudlike?',['it is unusually soft and fluffy','it is made of rainwater only','it has the exact shape of a mountain'],'it is unusually soft and fluffy','比喻云的轻柔蓬松特征。')]);
put('clove','clove 经古法语来自拉丁语 clavus（钉、丁香花蕾），既指作香料的干燥花蕾，也指蒜球中的一瓣。',c('clove.s2','厨房备料','He peeled one clove of garlic, crushed it with the flat of a knife, and stirred it into the warm oil.','他剥了一瓣大蒜，用刀面压碎后拌入温油中。','He peeled one clove of garlic / crushed it with the flat of a knife / and stirred it into the warm oil.','clove of garlic 是表示蒜瓣的量词结构；并列动词说明处理过程。','蒜球分出的一小瓣是 clove.s2。'),'She added one clove of garlic by pouring an entire bottle of garlic oil into the pan.','She added one clove of garlic by peeling a single section from the bulb.','一整瓶油不是蒜头的一瓣；clove 指蒜球的小分瓣。',[q('clove',1,1,'A clove of garlic is?',['one small section of a garlic bulb','the entire garlic plant','a cinnamon-coloured coat'],'one small section of a garlic bulb','clove.s2 指蒜头分瓣。'),q('clove',2,1,'The spice clove comes from?',['a dried flower bud','a fish’s fin','a tree’s root only'],'a dried flower bud','clove.s1 是丁香树的干燥花蕾香料。'),q('clove',3,2,'How much garlic does “two cloves” mean?',['two individual sections from bulbs','two whole fields of garlic','two teaspoons of cinnamon'],'two individual sections from bulbs','cloves 是蒜瓣的复数。'),q('clove',4,1,'Which dish might use cloves as a spice?',['a spiced stew with aromatic dried buds','a plain sheet of paper','a musical score with a clef'],'a spiced stew with aromatic dried buds','丁香是有强烈芳香的香料。')]);
put('clover','clover 源自古英语 clāfre，指通常由三片小叶组成的低矮豆科植物。',c('clover.s1','草地生态','Bees moved among the white clover blossoms in the field, while the broad three-part leaves formed a dense mat near the ground.','蜜蜂在田野的白色三叶草花间穿梭，而宽大的三片叶组成贴近地面的茂密植被层。','Bees moved among the white clover blossoms in the field / while the broad three-part leaves formed a dense mat near the ground.','clover 作 blossoms 的前置定语；while 对照花朵与叶片。','低矮植株和通常三片小叶是 clover.s1 特征。'),'The clover in the meadow had needle-shaped leaves arranged singly on a tall bare trunk.','The pine in the meadow had needle-shaped leaves arranged singly on a tall bare trunk.','针状单叶和高大树干更像松树，不符合三叶草特征。',[q('clover',1,1,'A typical clover leaf is divided into?',['three leaflets','two metal plates','five musical staffs'],'three leaflets','clover.s1 的叶通常分成三片小叶。'),q('clover',2,1,'Clover is generally?',['a low-growing plant','a large sea mammal','a metal used in batteries'],'a low-growing plant','三叶草是低矮植物。'),q('clover',3,1,'Which animal might visit clover blossoms for nectar?',['a bee','a codfish','a cockroach only'],'a bee','三叶草花可吸引蜜蜂采蜜。'),q('clover',4,1,'A four-leaf clover is unusual because clover leaves typically have?',['three leaflets','no leaves','only one flower petal'],'three leaflets','四叶变异之所以特别，是因为通常为三小叶。')]);
put('clump','clump 的词源不确定，英语中作名词指紧密的一丛或一团，作动词可指发出沉重脚步声地走。',c('clump.s2','楼道声响','The exhausted guard clumped up the metal stairs in heavy boots, waking the caretaker in the room above.','疲惫的守卫穿着厚靴，咚咚地走上金属楼梯，把楼上的管理员吵醒了。','The exhausted guard clumped up the metal stairs in heavy boots / waking the caretaker in the room above.','clumped 是谓语动词，描述脚步沉重；up 表示向上移动。','厚靴沉重地走楼梯发出响声，体现 clump.s2。'),'The guard clumped silently upstairs in soft slippers without making any sound.','The guard tiptoed silently upstairs in soft slippers without making any sound.','轻软鞋下无声移动是 tiptoe，与 clump 的沉重响步相反。',[q('clump',1,1,'A clump of trees is?',['a small close-growing group','one isolated pebble','a legal document'],'a small close-growing group','clump.s1 指紧密聚在一起的一丛。'),q('clump',2,2,'To clump down a hallway is to walk?',['with slow, heavy, noisy steps','silently on tiptoe','backward in midair'],'with slow, heavy, noisy steps','clump.s2 描述沉重而响亮的脚步。'),q('clump',3,1,'Which is a clump of earth?',['a compact lump of soil','a cloudburst of rain','a sheet of polished glass'],'a compact lump of soil','clump 可指一团或一块物质。'),q('clump',4,2,'The children clumped into the kitchen in wet boots. They?',['walked in noisily with heavy steps','floated in without touching the floor','whispered from outside'],'walked in noisily with heavy steps','clump 作动词表现沉重响亮的脚步。')]);
put('co-operation','co-operation 由 co-（共同）与 operation（协作行动）构成，指为共同目标互相配合；连字符拼写常见于英式英语。',c('co-operation.s1','团队协作','The rescue depended on co-operation between the ferry crew and shore volunteers, who relayed names and blankets across the pier.','救援依靠渡船船员与岸上志愿者合作，双方在码头接力传递姓名名单和毯子。','The rescue depended on co-operation between the ferry crew and shore volunteers / who relayed names and blankets across the pier.','co-operation 是 depended on 的宾语；between 引出协作双方。','不同团队为同一救援目标配合，符合 co-operation.s1。'),'The rescue succeeded through co-operation because every team refused to share information or help.','The rescue failed without co-operation because every team refused to share information or help.','拒绝分享和协助意味着缺乏合作，而非通过合作取得成功。',[q('co-operation',1,1,'Co-operation means?',['people or groups working together','one person acting entirely alone','a noisy demand for payment'],'people or groups working together','co-operation.s1 指共同协作。'),q('co-operation',2,1,'Which scene shows co-operation?',['two crews sharing tasks during a rescue','each crew hiding supplies from the other','one crew refusing to answer calls'],'two crews sharing tasks during a rescue','共同分担任务体现合作。'),q('co-operation',3,1,'The prefix co- in co-operation contributes the idea of?',['together','underwater','against all others'],'together','co- 表示共同、一起。'),q('co-operation',4,1,'A project needs co-operation when participants must?',['coordinate their efforts toward a shared goal','avoid all contact with one another','compete to destroy the project'],'coordinate their efforts toward a shared goal','协调协作才能完成共同目标。')]);
put('co-operative','co-operative 由 co-（共同）与 operative（起作用、运作）构成，可作形容词指愿意协作，也可作名词指由成员共同拥有经营的合作社。',c('co-operative.s2','农业经营','The dairy co-operative collected milk from dozens of farms, processed it in a shared plant, and returned profits to its member producers.','这家乳品合作社从数十个农场收奶，在共同工厂加工，再把利润返还给成员生产者。','The dairy co-operative collected milk from dozens of farms / processed it in a shared plant / and returned profits to its member producers.','co-operative 作主语名词；共同设施和成员分红说明合作社结构。','由成员共同经营并分享收益的企业是 co-operative.s2。'),'The dairy co-operative was owned by one distant investor, while its farmers had no membership or share.','The private dairy company was owned by one distant investor, while its farmers had no membership or share.','成员不拥有或参与企业的结构不是合作社；private company 更合适。',[q('co-operative',1,1,'A co-operative colleague is?',['willing to work with others','deliberately obstructive','a building made from clay'],'willing to work with others','co-operative.s1 作形容词表示合作、愿意配合。'),q('co-operative',2,2,'A consumer co-operative is typically?',['a business owned and run by its members','a state of bad weather','a group of unrelated customers with no shared ownership'],'a business owned and run by its members','co-operative.s2 指成员共同拥有经营的企业。'),q('co-operative',3,1,'Which worker is being co-operative?',['one who shares information and helps the team','one who hides the tools and refuses all requests','one who leaves every task unfinished'],'one who shares information and helps the team','主动协助团队体现合作态度。'),q('co-operative',4,2,'In a farmers’ co-operative, the member farmers?',['jointly own or run the enterprise','are merely its weather forecasters','have no connection to its business'],'jointly own or run the enterprise','合作社由成员共同持有或管理。')]);

put('co-worker','co-worker 由 co-（共同）与 worker（工作者）构成，可指同一单位的同事，也可指共同完成某项任务的合作者。',c('co-worker.s2','科研项目','The field biologist thanked her co-worker, who had joined the survey only for one week to identify the unfamiliar bird calls.','这位野外生物学家感谢她的合作者；对方只参加了一周调查，就帮忙辨认那些陌生鸟鸣。','The field biologist thanked her co-worker / who had joined the survey only for one week / to identify the unfamiliar bird calls.','co-worker 是 thanked 的宾语；who 从句说明该合作者的任务。','临时加入并共同完成调查任务，体现 co-worker.s2。'),'The biologist’s co-worker had no part in the survey and never helped with the shared task.','The biologist’s visitor had no part in the survey and never helped with the shared task.','不参与共同工作的人不构成该任务的 co-worker。',[q('co-worker',1,1,'A co-worker is generally?',['someone who works with you','a person who employs you necessarily','a customer buying a product'],'someone who works with you','co-worker.s1 指同事。'),q('co-worker',2,2,'A co-worker on a one-time research task is?',['a collaborator working with you on that task','a person who refuses to take part','the species being observed'],'a collaborator working with you on that task','co-worker.s2 可指共同做一项任务的人。'),q('co-worker',3,1,'Which person is your co-worker?',['a colleague on the same team','a stranger who merely walks past','the building where you work'],'a colleague on the same team','在同一团队工作的人是同事。'),q('co-worker',4,2,'A visiting scientist who helps run your experiment is your?',['co-worker on the project','employer in every case','research specimen'],'co-worker on the project','共同参与项目的合作者可称 co-worker。')]);
put('coachload','coachload 由 coach（长途客车）与 load（载量）构成，常指一整车长途客车的乘客或货物。',c('coachload.s1','旅游接待','A coachload of visitors arrived at the castle just before opening, and the guides divided them into smaller groups for the tour.','一整车游客在城堡开放前抵达，导游把他们分成较小的团体参观。','A coachload of visitors arrived at the castle just before opening / and the guides divided them into smaller groups for the tour.','coachload 作量词式名词修饰 visitors；and 连接抵达与分组。','一辆客车所载的整批游客符合 coachload.s1。'),'A coachload of tourists means one tourist walking alone without any vehicle.','A lone tourist means one tourist walking alone without any vehicle.','coachload 指可由一辆客车运载的一群人，不是单独步行者。',[q('coachload',1,1,'A coachload of schoolchildren is?',['as many children as one coach carries','one child walking alone','a group that fills a swimming pool'],'as many children as one coach carries','coachload.s1 指一辆客车可载的一车人。'),q('coachload',2,1,'A museum receives a coachload of visitors. They likely arrive?',['together on one coach','one at a time by submarine','as a single museum employee'],'together on one coach','coachload 强调整车乘客的数量。'),q('coachload',3,1,'The suffix element load in coachload refers to?',['the amount carried','a legal ruling','a musical pitch'],'the amount carried','load 表示所承载的数量。'),q('coachload',4,1,'Which arrival could be described as a coachload?',['forty tourists transported by one tour bus','one cyclist arriving alone','a box of postcards delivered by mail'],'forty tourists transported by one tour bus','一车旅游乘客是一 coachload。')]);
put('coagulation','coagulation 由 coagulate 加 -ion 构成，源自拉丁语 coagulare（使凝结），指液体变稠、聚结成较稠团块的过程。',c('coagulation.s1','生物实验','The coagulation of the sample began after the technician added the reagent, turning the thin liquid into a soft gel.','技师加入试剂后，样本开始凝结，稀薄液体逐渐变成柔软的凝胶。','The coagulation of the sample began after the technician added the reagent / turning the thin liquid into a soft gel.','coagulation 作 began 的主语；turning 分词短语描述变化结果。','液体变为较稠凝胶体现 coagulation.s1。'),'Coagulation kept the blood perfectly liquid and prevented every clot from forming.','Anticoagulation helped keep the blood liquid and prevented a clot from forming.','coagulation 是凝结成块；阻止凝块形成属于抗凝。',[q('coagulation',1,1,'Coagulation is the process by which a liquid?',['thickens or forms a soft solid mass','evaporates without any change','becomes a musical instrument'],'thickens or forms a soft solid mass','coagulation.s1 指液体凝结变稠。'),q('coagulation',2,1,'Blood coagulation helps?',['form a clot at an injury','turn blood into oxygen gas','remove every blood cell'],'form a clot at an injury','血液凝固可形成血块以止血。'),q('coagulation',3,1,'Which result suggests coagulation?',['a formerly thin solution forms a gel','a solid metal disappears into sound','a dry towel becomes a cloud'],'a formerly thin solution forms a gel','形成凝胶说明液体变稠聚结。'),q('coagulation',4,1,'A laboratory studies coagulation when it observes?',['how particles make a liquid thicken','how coastlines change on a map','how a bus carries passengers'],'how particles make a liquid thicken','观察液体变稠、凝结属于该过程。')]);
put('coalesce','coalesce 源自拉丁语 coalescere（长到一起），由 co-（一起）与 alescere（生长）组成，指逐渐合并成整体。',c('coalesce.s1','社会运动','Several neighbourhood groups began to coalesce around a shared campaign for safer crossings after a child was injured near the school.','一名儿童在学校附近受伤后，几个社区团体开始围绕改善过街安全的共同运动逐渐联合起来。','Several neighbourhood groups began to coalesce around a shared campaign / after a child was injured near the school.','coalesce 不及物，around 引出团结的共同目标。','多个团体逐渐并为一个行动阵线，符合 coalesce.s1。'),'The neighbourhood groups coalesced by splitting apart into smaller groups with no shared aim.','The neighbourhood groups fragmented by splitting apart into smaller groups with no shared aim.','分裂成彼此独立小组是 fragment，不是 coalesce。',[q('coalesce',1,1,'When separate groups coalesce, they?',['come together as one','move farther apart permanently','lose every member'],'come together as one','coalesce.s1 表示逐渐合并成整体。'),q('coalesce',2,1,'Several droplets coalesce into a larger drop when they?',['join together','freeze at separate locations','turn into dry dust'],'join together','小液滴结合成较大液滴是 coalesce。'),q('coalesce',3,1,'A coalition coalesced around one proposal. The members?',['gradually united behind it','each rejected all common action','left the meeting before hearing it'],'gradually united behind it','团体围绕共同提案联合起来。'),q('coalesce',4,1,'Which process is coalescence in verb form?',['small streams merging into one river','one river branching into unrelated dry valleys','rain evaporating before it falls'],'small streams merging into one river','汇流成一体体现 coalesce。')]);
put('coalescence','coalescence 由 coalesce 加名词后缀 -ence 构成，指分离的群体、液滴或想法逐渐融合的过程或结果。',c('coalescence.s1','地貌变化','The coalescence of three small streams created a single channel wide enough to carry the spring runoff through the valley.','三条小溪汇合成一条河道，宽到足以把春季径流带过山谷。','The coalescence of three small streams created a single channel / wide enough to carry the spring runoff / through the valley.','coalescence 作 created 的主语；of 短语指出汇合对象。','多条溪流合为一条水道是 coalescence.s1。'),'The coalescence of the streams left them farther apart in separate valleys.','The separation of the streams left them farther apart in separate valleys.','分处不同山谷表示分离，和融合义相反。',[q('coalescence',1,1,'Coalescence is?',['the process of separate things joining into one','the act of dividing a whole into parts','the measurement of a circular boundary'],'the process of separate things joining into one','coalescence.s1 指逐渐合并的过程或结果。'),q('coalescence',2,1,'The coalescence of droplets produces?',['a larger combined drop','many smaller separate drops','a dry patch of sand'],'a larger combined drop','液滴合并形成更大液滴。'),q('coalescence',3,1,'Political coalescence can occur when groups?',['unite around shared goals','refuse all cooperation','become geographically distant'],'unite around shared goals','团体围绕共同目标联合是比喻义。'),q('coalescence',4,1,'Which event illustrates coalescence?',['two ideas blending into one coherent plan','a river splitting into isolated trickles','a committee scattering without agreement'],'two ideas blending into one coherent plan','不同想法融合成方案体现 coalescence。')]);
put('coaming','coaming 是航海英语中的专门术语，具体词源不确定；它指船舶舱口或驾驶舱开口周围凸起的挡水围板。',c('coaming.s1','船舶安全','The deckhand cleared leaves from the hatch coaming so rainwater would drain away instead of spilling into the lower compartment.','甲板水手清除了舱口围板上的树叶，使雨水排走而不是流进下层舱室。','The deckhand cleared leaves from the hatch coaming / so rainwater would drain away / instead of spilling into the lower compartment.','coaming 是介词 from 的宾语；so 从句说明清理目的。','舱口周围的凸起挡边防止水灌入船舱。'),'Water poured below deck because the coaming was a flat opening with no raised edge.','Water poured below deck because the hatch had no raised coaming to keep it out.','coaming 正是开口周围凸起的挡水边，不是平坦无边的洞口。',[q('coaming',1,1,'A ship’s coaming is?',['a raised rim around a hatch or cockpit','a rope tied to the mast','a passenger list'],'a raised rim around a hatch or cockpit','coaming.s1 指舱口或驾驶舱开口周围的凸边。'),q('coaming',2,1,'Why does a hatch coaming rise above the deck?',['to help keep water from entering below','to carry passengers across the ocean','to support a musical keyboard'],'to help keep water from entering below','凸起围板可阻水进入船内。'),q('coaming',3,1,'A deckhand checks the coaming when inspecting?',['the raised edge around an opening','the ship’s citizenship documents','the colour of the coastline'],'the raised edge around an opening','coaming 指开口边缘的围板。'),q('coaming',4,1,'Which part of a boat is a coaming?',['the raised border of a hatch','the anchor chain’s far end','the captain’s written citation'],'the raised border of a hatch','舱口周围的凸起边就是 coaming。')]);
put('coarsely','coarsely 由 coarse 加副词后缀 -ly 构成，可指颗粒粗大地处理，也可指言辞粗俗无礼地表达。',c('coarsely.s2','人物评价','The customer spoke coarsely to the cashier, using insulting language that made the people waiting behind him fall silent.','顾客粗鲁地对收银员说话，用了侮辱性语言，让排在他后面的人都沉默下来。','The customer spoke coarsely to the cashier / using insulting language / that made the people waiting behind him fall silent.','coarsely 修饰 spoke；that 从句修饰 insulting language。','侮辱性言语体现 coarsely.s2 的粗俗无礼义。'),'She addressed the cashier coarsely by choosing considerate words and apologizing for the delay.','She addressed the cashier politely by choosing considerate words and apologizing for the delay.','体贴措辞并道歉是礼貌表达，与 coarsely 相反。',[q('coarsely',1,1,'If carrots are chopped coarsely, the pieces are?',['large and roughly cut','finely grated into tiny strands','left completely whole'],'large and roughly cut','coarsely.s1 指粗略、粗颗粒地处理。'),q('coarsely',2,2,'If someone speaks coarsely, the language is?',['rude or vulgar','carefully formal and courteous','silent and unspoken'],'rude or vulgar','coarsely.s2 指粗俗无礼地说话。'),q('coarsely',3,1,'Which instruction asks for a coarse texture?',['grind the pepper into large rough pieces','powder it until no grains remain','dissolve every grain in water'],'grind the pepper into large rough pieces','粗研磨保留较大颗粒。'),q('coarsely',4,2,'A coarsely worded insult is?',['vulgar and offensive','quietly complimentary','precise but neutral'],'vulgar and offensive','粗俗冒犯的语言符合第二义。')]);
put('coastland','coastland 由 coast 与 land 组合而成，指沿海或靠近海岸的陆地；有些用法特指海边低地。',c('coastland.s2','环境地理','Much of the coastland behind the dunes is low and flat, so engineers raised the road before the winter tides reached it.','沙丘后方大部分沿海低地平坦，因此工程师在冬季潮水抵达前抬高了道路。','Much of the coastland behind the dunes is low and flat / so engineers raised the road / before the winter tides reached it.','coastland 作主语；so 从句说明地势引发的工程措施。','靠海且平坦低洼的土地符合 coastland.s2。'),'The coastland was a high inland plateau hundreds of miles from the sea.','The upland was a high plateau hundreds of miles from the sea.','远离海岸的高原不属于 coastland；upland 符合描述。',[q('coastland',1,1,'Coastland is?',['land along or near the sea','a deep area beneath the ocean','a city far inland with no nearby shore'],'land along or near the sea','coastland.s1 指沿海陆地。'),q('coastland',2,2,'Low coastland is often?',['flat land beside the sea','a mountain summit far inland','an underground cave'],'flat land beside the sea','部分用法特别指沿海低地。'),q('coastland',3,1,'A planner assessing coastland should consider?',['sea-level rise and coastal flooding','the pitch of a clavichord','the spelling of an essay citation'],'sea-level rise and coastal flooding','沿海地区规划须考虑潮位和海水淹没。'),q('coastland',4,2,'Which site is coastland?',['a low plain beside an ocean','a plateau deep in a continent','a ridge above a landlocked desert'],'a low plain beside an ocean','临海低地符合 coastland。')]);
put('coastline','coastline 由 coast 与 line 组合而成，指陆地与海洋相接的海岸边界及其形状或总长度。',c('coastline.s1','地理测绘','The new satellite map traced the coastline around the bay, revealing several small inlets hidden by the older chart.','新的卫星地图描绘了海湾周围的海岸线，显示出旧海图未标出的几个小海湾。','The new satellite map traced the coastline around the bay / revealing several small inlets / hidden by the older chart.','coastline 是 traced 的宾语；revealing 分词说明新地图呈现的信息。','地图上的陆海交界线是 coastline.s1。'),'The coastline marks the border between two inland deserts with no sea nearby.','The land boundary marks the border between two inland deserts with no sea nearby.','coastline 专指海陆交界，不适用于无海内陆沙漠的边界。',[q('coastline',1,1,'A coastline is the boundary where?',['land meets the sea','two rooms meet inside a house','a river meets a mountain peak'],'land meets the sea','coastline.s1 指陆海交界线。'),q('coastline',2,1,'A mapmaker tracing a coastline records?',['the shore’s shape and course','the population of a distant city','the area of a building’s roof'],'the shore’s shape and course','海岸线体现海岸形状及走向。'),q('coastline',3,1,'An island’s coastline may include?',['bays, headlands, and inlets','only its highest mountain','its national anthem'],'bays, headlands, and inlets','这些地形构成岛屿海岸边界。'),q('coastline',4,1,'Erosion can change a coastline by?',['wearing away cliffs and beaches','altering a musical clef','changing a person’s citizenship'],'wearing away cliffs and beaches','侵蚀会改变海岸的形状或位置。')]);
put('cob','cob 的具体词源不确定；它早期可指圆块或玉米穗轴，较少见的动词义是把硬物敲碎。',c('cob.s2','建筑回收','The crew cobbed the broken bricks into smaller pieces before mixing them with rubble for the path foundation.','工人把碎砖敲成小块，再将它们与碎石混合用作小路地基。','The crew cobbed the broken bricks into smaller pieces / before mixing them with rubble / for the path foundation.','cob 作及物动词，后接被敲碎的 bricks。','把硬砖敲碎是 cob.s2 的罕见动词义。'),'The crew cobbed the bricks by polishing each one until it was larger and intact.','The crew preserved the bricks by keeping each one intact and unbroken.','敲碎与完整保留是相反操作；后句改为保持原状。',[q('cob',1,1,'A corn cob is the?',['central core of an ear of maize','flower bud used as a spice','shell of a sea clam'],'central core of an ear of maize','cob.s1 指玉米穗轴。'),q('cob',2,2,'In the rare verb sense, to cob a hard material is to?',['break it into smaller pieces','polish it without changing its shape','turn it into a liquid'],'break it into smaller pieces','cob.s2 指把硬物敲碎。'),q('cob',3,1,'A child eating corn on the cob is eating corn?',['still attached to its central core','ground into fine flour only','mixed into a glass of milk'],'still attached to its central core','on the cob 表示玉米粒仍附在穗轴上。'),q('cob',4,2,'Workers cob old bricks before reuse when they?',['crush them into smaller pieces','paint them without touching them','sort them by colour only'],'crush them into smaller pieces','敲碎旧砖体现动词义。')]);

put('cobalt','cobalt 的名称经德语 Kobalt 来自 Kobold（矿山精怪），源于早期矿工将难以冶炼的钴矿视作受精怪作祟；元素符号为 Co。',c('cobalt.s1','玻璃工艺','The glassmaker added a small amount of cobalt compound to the molten glass, producing a deep blue rather than the metal’s usual silvery grey.','玻璃工匠在熔融玻璃中加入少量钴化合物，使玻璃呈深蓝色，而钴金属本身通常呈银灰色。','The glassmaker added a small amount of cobalt compound to the molten glass / producing a deep blue / rather than the metal’s usual silvery grey.','cobalt 修饰 compound；producing 分词说明加入后的颜色效果。','钴化合物用于制造钴蓝色颜料和玻璃。'),'The cobalt pigment made the glass bright green because cobalt is a soft yellow gas.','The chromium pigment made the glass bright green because chromium compounds can produce green glass.','钴是金属而非黄色气体；这里改为能产生绿色玻璃的铬化合物。',[q('cobalt',1,1,'Cobalt is a chemical element with symbol?',['Co','Cb','Ct'],'Co','cobalt.s1 是元素钴，符号为 Co。'),q('cobalt',2,1,'Cobalt metal is typically?',['silvery grey','bright transparent green gas','soft white paper'],'silvery grey','金属钴通常呈银灰色；其化合物可呈蓝色。'),q('cobalt',3,1,'Cobalt blue gets its colour from?',['cobalt compounds used as pigment','the blue surface of pure copper','a coating of cinnamon'],'cobalt compounds used as pigment','钴化合物可制成深蓝色颜料。'),q('cobalt',4,1,'Which industry may use cobalt compounds?',['glass and pigment making','bookbinding only','roadside gardening only'],'glass and pigment making','钴化合物可用于颜料及玻璃着色。')]);
put('cobble','cobble 可能与表示圆石的中古英语词有关；名词指铺路小圆石，动词 cobble together 常指仓促粗糙地拼凑。',c('cobble.s2','项目赶工','With only one day left, the analysts cobbled together a short report from verified figures and clearly marked the sections still needing review.','只剩一天时，分析师用已核实的数据匆忙拼成一份简短报告，并清楚标出仍待复查的部分。','With only one day left / the analysts cobbled together a short report from verified figures / and clearly marked the sections still needing review.','cobbled together 是过去式动词短语，表示仓促拼凑；from 引出材料。','短时间把材料凑成报告体现 cobble.s2。'),'They cobbled together a report by spending months carefully drafting every section from scratch.','They carefully prepared a report by spending months drafting every section from scratch.','历时数月精心起草与匆忙拼凑相反。',[q('cobble',1,1,'A cobble in an old street is?',['a small rounded paving stone','a metal musical key','a piece of citrus fruit'],'a small rounded paving stone','cobble.s1 指用于铺路的小圆石。'),q('cobble',2,2,'To cobble together a plan is to?',['put it together roughly and quickly','polish it for years in perfect detail','erase it without making another'],'put it together roughly and quickly','cobble.s2 指匆忙粗略拼凑。'),q('cobble',3,1,'A street of cobbles is paved with?',['rounded stones','soft cushions','cloves of garlic'],'rounded stones','鹅卵石铺面由圆石组成。'),q('cobble',4,2,'Which action best describes cobbling together a team?',['assembling available people quickly, with little planning','training one fixed team for many years','disbanding all workers'],'assembling available people quickly, with little planning','临时快速拼成团队体现 cobble together。')]);
put('cockroach','cockroach 经英语对西班牙语 cucaracha 的民间改造形成，词形虽含 cock，却与公鸡无关，指常见扁身昆虫蟑螂。',c('cockroach.s1','家庭卫生','A cockroach ran beneath the refrigerator when the kitchen light came on, and the caretaker sealed a crack beside the drain.','厨房灯亮起时，一只蟑螂钻到冰箱下面，管理员便封住排水口旁的一道缝。','A cockroach ran beneath the refrigerator / when the kitchen light came on / and the caretaker sealed a crack beside the drain.','cockroach 是 ran 的主语；when 从句交代昆虫受惊逃窜的时刻。','室内常见、扁身且行动迅速的昆虫是蟑螂。'),'The cockroach was a small mammal with fur, hooves, and no antennae.','The cockroach was a flat-bodied insect with long antennae.','蟑螂是昆虫，有触角，并非长毛有蹄的哺乳动物。',[q('cockroach',1,1,'A cockroach is?',['a flat-bodied insect with long antennae','a furry mammal with hooves','a sea fish with scales'],'a flat-bodied insect with long antennae','cockroach.s1 指身体扁平、触角较长的常见昆虫。'),q('cockroach',2,1,'Where might a cockroach commonly be found?',['inside a building near food or water','inside a musical staff','only on the surface of the moon'],'inside a building near food or water','蟑螂常在建筑物内活动。'),q('cockroach',3,1,'Which clue suggests that an animal is a cockroach?',['it has a flattened body and long antennae','it has feathers and lays large eggs','it has a shell with two valves'],'it has a flattened body and long antennae','扁身和长触角是蟑螂的识别特征。'),q('cockroach',4,1,'Cockroach is historically related in spelling to?',['Spanish cucaracha, reshaped in English','the English word for a rooster','the word for a sea clam'],'Spanish cucaracha, reshaped in English','词形经英语对西班牙语 cucaracha 的民间改造而来。')]);
put('cod','cod 的词源不确定，英语中长期用作北方海域大型食用鱼的名称；较少见的动词用法表示戏弄或哄骗。',c('cod.s2','英式口语','“I’m only codding you about the prize,” Liam said, making clear that the supposed lottery win was a joke.','利亚姆说：“我只是拿奖品的事逗你玩。”他表明所谓中奖不过是个玩笑。','“I’m only codding you about the prize,” Liam said / making clear that the supposed lottery win was a joke.','cod 的进行时形式 codding 出现在 codding someone about something 的搭配中。','用中奖消息开玩笑地捉弄人体现 cod.s2。'),'He codded her by giving a sincere warning and never pretending that anything had happened.','He warned her sincerely and never pretended that anything had happened.','真诚提醒而非戏弄或假装，不能称为 cod someone。',[q('cod',1,1,'Cod as food is?',['a large sea fish','a small tree spice','a type of freshwater grass'],'a large sea fish','cod.s1 指北方海域常见的大型食用鱼。'),q('cod',2,2,'In informal British use, to cod someone is to?',['tease or trick them playfully','serve them a fish dinner','measure their height'],'tease or trick them playfully','cod.s2 是口语中的戏弄、哄骗义。'),q('cod',3,1,'A menu offering baked cod serves?',['fish','a clove of garlic','a clay pot'],'fish','菜单中的 cod 通常是鳕鱼。'),q('cod',4,2,'“I was only codding you” means?',['I was just teasing you','I was measuring a coastline','I was issuing a legal citation'],'I was just teasing you','codding 是动词 cod 的变形，指开玩笑捉弄。')]);
put('coddle','coddle 的词源可能与早期表示温热饮品的 caudle 有关，现代既指过分呵护，也指用低于沸点的热水温和煮蛋。',c('coddle.s2','烹饪技巧','To coddle the eggs, Nia lowered them into barely simmering water and watched closely so the whites set while the yolks stayed soft.','为了温煮鸡蛋，妮娅把鸡蛋放入刚刚冒小泡的水中，仔细观察，让蛋白凝固而蛋黄仍保持柔软。','To coddle the eggs / Nia lowered them into barely simmering water / and watched closely / so the whites set while the yolks stayed soft.','coddle 是不定式动词，说明烹调方法；so 从句交代蛋白和蛋黄的结果。','低温轻煮鸡蛋是 coddle.s2。'),'She coddled the eggs by boiling them violently for an hour until both yolks and whites became hard.','She hard-boiled the eggs by boiling them vigorously until both yolks and whites became firm.','长时间沸腾煮至全熟不是温和低温的 coddle。',[q('coddle',1,1,'To coddle a child is to?',['treat the child with excessive care','leave the child entirely unattended','teach the child to identify a clef'],'treat the child with excessive care','coddle.s1 指过分呵护、娇养。'),q('coddle',2,2,'To coddle an egg is to?',['cook it gently in hot water below a full boil','fry it until crisp in deep oil','freeze it until solid'],'cook it gently in hot water below a full boil','coddle.s2 指温和地煮蛋。'),q('coddle',3,1,'Which parent might be accused of coddling?',['one who never lets a capable teenager solve small problems','one who expects age-appropriate responsibility','one who gives clear safety instructions'],'one who never lets a capable teenager solve small problems','不让孩子面对小问题、保护过度，属于娇养。'),q('coddle',4,2,'A coddled egg generally has?',['a gently set white and soft yolk','a shell dissolved by acid','a completely frozen interior'],'a gently set white and soft yolk','低温温煮能使蛋白凝固、蛋黄柔软。')]);
put('codification','codification 由 codify 加名词后缀 -ation 构成，源于 code（法典、规则），指把法律、习俗或原则整理成系统规则的过程。',c('codification.s1','法律史','The codification of local customs gave judges a written reference and helped residents learn which rules applied across the province.','地方习俗编纂成典后，法官有了书面参考，居民也更容易了解全省适用的规则。','The codification of local customs gave judges a written reference / and helped residents learn / which rules applied across the province.','codification 作主语；of 短语指出被整理成典的内容。','把习俗汇编为有序规则是 codification.s1。'),'The codification of the laws made them less organized by scattering each rule across unrelated notebooks.','The fragmentation of the laws made them less organized by scattering each rule across unrelated notebooks.','把规则分散且失序是 fragmentation，不是系统编纂。',[q('codification',1,1,'Codification is the process of?',['organizing rules into a formal system or code','deleting every rule from a society','quoting a source without naming it'],'organizing rules into a formal system or code','codification.s1 指规则系统化、编纂成典。'),q('codification',2,1,'A codification of customs can help by?',['collecting them in an ordered written form','making them impossible to find','replacing them with unrelated recipes'],'collecting them in an ordered written form','书面汇编使习俗更有序易查。'),q('codification',3,1,'Which project is codification?',['arranging court rules into a clear legal code','painting a courthouse wall blue','measuring the building’s coastline'],'arranging court rules into a clear legal code','把法律规则整理成法典即 codification。'),q('codification',4,1,'Codification concerns the organization of?',['laws, customs, or principles','hair clippers and musical strings','clouds and sea waves only'],'laws, customs, or principles','规则、习俗、原则都可以被编纂成体系。')]);
put('codify','codify 由 code 与动词后缀 -ify 构成，指把法律、规则、惯例或原则编成正式体系。',c('codify.s1','安全规范','The standards board will codify the laboratory’s informal safety practices so every branch follows the same written procedures.','标准委员会将把实验室非正式的安全惯例编成规则，使每个分部都遵循相同的书面程序。','The standards board will codify the laboratory’s informal safety practices / so every branch follows the same written procedures.','codify 是 will 后动词原形，宾语为安全惯例；so 从句说明目的。','把做法正式整理为统一程序符合 codify.s1。'),'The board will codify the safety practices by leaving them unwritten and different at every branch.','The board will decentralize the safety practices by leaving them unwritten and different at every branch.','不成文且各自不同与编成统一正式规则相反。',[q('codify',1,1,'To codify a principle is to?',['arrange it into a formal system','erase it from every record','change it into a musical note'],'arrange it into a formal system','codify.s1 指将原则整理为正式体系。'),q('codify',2,1,'A legislature may codify laws by?',['collecting and organizing them into a code','hiding them from the public','turning each law into a private rumour'],'collecting and organizing them into a code','编纂法典会汇总并系统整理法律。'),q('codify',3,1,'Which sentence uses codify correctly?',['The agency codified its procedures in a published manual.','The agency codified the storm into a rainfall.','The agency codified by refusing to write anything down.'],'The agency codified its procedures in a published manual.','书面手册把程序正式系统化。'),q('codify',4,1,'A company codifies a workplace practice when it?',['writes the practice into an official policy','keeps the practice secret and inconsistent','removes it from every training guide'],'writes the practice into an official policy','将惯例正式写进制度就是 codify。')]);
put('coed','coed 是 coeducational 的缩略形式；作名词时，尤在较早的美国用法中，指男女同校大学里的女学生。',c('coed.s1','校园史','The memoir follows a coed at a mixed college in the 1950s, describing her classes, dormitory rules, and first student election.','这本回忆录讲述一位20世纪50年代男女同校大学女学生的经历，包括课程、宿舍规定和第一次学生选举。','The memoir follows a coed at a mixed college in the 1950s / describing her classes, dormitory rules, and first student election.','coed 作 follows 的宾语；at 短语交代她就读的院校类型。','男女同校学院中的女学生符合 coed.s1。'),'The novel calls a male student at an all-boys school a coed because the school admits only boys.','The novel calls a female student at a mixed college a coed.','coed 在此名词义指男女同校学院中的女学生，不是全男校男生。',[q('coed',1,1,'In its older American noun use, a coed is?',['a female student at a mixed college','a male student at an all-boys school','a person who repairs clocks'],'a female student at a mixed college','coed.s1 指男女同校大学里的女学生。'),q('coed',2,1,'The word coed is shortened from?',['coeducational','coefficient','coastland'],'coeducational','coed 是 coeducational 的缩写。'),q('coed',3,1,'A novel about a coed at a mixed college would likely feature?',['a female student’s campus life','a ship’s raised hatch rim','a codification of criminal law'],'a female student’s campus life','coed 描写在男女同校学院就读的女性学生。'),q('coed',4,1,'Which usage reflects the noun coed?',['a woman enrolled at a coeducational college','any school building that admits students','a student’s citizenship document'],'a woman enrolled at a coeducational college','该名词义专指男女同校院校的女学生。')]);
put('coeducation','coeducation 由 co-（共同）与 education 构成，指男女学生在同一学校共同接受教育的制度。',c('coeducation.s1','教育制度','The college introduced coeducation in 1972, allowing women and men to enroll in the same courses and live in designated campus housing.','这所学院于1972年实行男女同校，使女性和男性可以选修同一课程并住进指定校舍。','The college introduced coeducation in 1972 / allowing women and men to enroll in the same courses / and live in designated campus housing.','coeducation 是 introduced 的宾语；allowing 分词说明制度变化的结果。','男女学生共同就读同一学校与课程体现 coeducation.s1。'),'The college adopted coeducation by separating male and female students into permanently different schools.','The college adopted single-sex education by separating male and female students into different schools.','男女分校与男女同校相反，后者才是 coeducation。',[q('coeducation',1,1,'Coeducation is a system in which?',['male and female students study together','only one student studies at home','teachers and students never meet'],'male and female students study together','coeducation.s1 指男女同校教育。'),q('coeducation',2,1,'A school introducing coeducation would?',['admit girls and boys to study in the same school','divide all pupils into separate schools by sex','stop teaching every subject'],'admit girls and boys to study in the same school','男女学生共同学习构成 coeducation。'),q('coeducation',3,1,'Which policy is coeducation?',['women and men share classes at one college','women may attend only a separate campus','men alone may enroll'],'women and men share classes at one college','同一学校共同上课是 coeducation。'),q('coeducation',4,1,'The prefix co- in coeducation signals?',['together','secretly','afterward'],'together','co- 表示共同，体现男女一起受教育。')]);
put('coefficient','coefficient 经新拉丁语 coefficientia 构成，含 co-（共同）与 efficient（起作用）成分；数学中指乘在变量前的数，科学中也指关系度量值。',c('coefficient.s1','代数课堂','In the expression 7y − 4, the coefficient of y is 7 because it multiplies the variable.','在表达式7y−4中，y的系数是7，因为它乘在该变量前。','In the expression 7y − 4 / the coefficient of y is 7 / because it multiplies the variable.','coefficient 是 is 的表语；of y 指明对应变量。','乘在变量 y 前的数字7是系数。'),'In 7y − 4, the coefficient of y is −4 because it is the constant term.','In 7y − 4, the constant term is −4; the coefficient of y is 7.','−4 是常数项，不乘 y；y 的系数为7。',[q('coefficient',1,1,'In 5x + 2, the coefficient of x is?',['5','2','x'],'5','coefficient.s1 是乘在变量前的数。'),q('coefficient',2,1,'A friction coefficient is a number used to?',['measure a relation between surfaces and friction','name a type of sea fish','show where a sentence ends'],'measure a relation between surfaces and friction','科学中的 coefficient 可表示某种关系的度量数值。'),q('coefficient',3,1,'In −3a, which part is the coefficient?',['−3','a','the entire alphabet'],'−3','负号也属于乘在变量前的系数。'),q('coefficient',4,1,'If z appears as z with no number written before it, its coefficient is?',['1','0','z squared'],'1','未写出的乘数默认为1。')]);


})();
